// Üretilen dosya: tool/ozgun/uret.py. Tarih · Anadolu uygarlıkları, Anadolu beylikleri ve Türkiye Selçuklu şehir-ticaret hayatı (Hitit, Urartu, Frig, Lidya, İyonya, beylikler, kervansaraylar, Ahilik) (orta).
const ozHistory15Orta = <(String, String, List<String>, String)>[
  ('Hitit Kralı Telepinuş tarafından yayımlanan ferman, devletin siyasi tarihinde özellikle hangi kronik sorunu çözmeye yönelik kalıcı bir kural getirmiştir?', 'Tahta geçiş esaslarını belirleyerek hanedan içi kanlı mücadeleleri önleme', ['Tapınak rahiplerinin tarım toprakları üzerindeki vergi muafiyetini kaldırma', 'Asurlu tüccarların Anadolu pazarlarındaki gümrük ayrıcalıklarını sonlandırma', 'Savaş esirlerinin mülk edinme ve özgür bireylerle evlenme haklarını yasaklama'], 'Telepinuş Fermanı, kraldan sonra ilk sıradaki meşru oğlun tahta geçmesini kurala bağlayarak taht kavgalarını engellemeyi amaçlamıştır.'),
  ('Çorum\'un Boğazkale ilçesi sınırlarında bulunan ve doğal kaya galerileri üzerine tanrı ile tanrıçaların geçit töreni kabartmalarının işlendiği Hitit açık hava tapınağı hangisidir?', 'Yazılıkaya', ['Altıntepe', 'Çavuştepe', 'Gavurkalesi'], 'Hattuşa yakınlarındaki Yazılıkaya Açık Hava Tapınağı, Hitit panteonundaki tanrıların kabartmalarıyla ünlü en önemli kutsal alandır.'),
  ('Babil ve Asur hukukundaki sert \'kısasa kısas\' ilkesiyle kıyaslandığında Hitit kanunlarını çağdaşlarından ayıran temel hukuki yaklaşım nedir?', 'Suçların karşılığında bedensel ceza yerine maddi tazminat esasının öne çıkması', ['Yargılamaların tümüyle halk jürileri tarafından açık meydanlarda yürütülmesi', 'Kölelerin özgür yurttaşlarla hiçbir fark gözetilmeksizin eşit cezaya çarptırılması', 'Yazılı kurallar yerine yalnızca rahiplerin kehanetlerine dayanarak hüküm verilmesi'], 'Hitit hukuku Mezopotamya\'nın kısas anlayışından daha insancıldır; çoğu suçta zarar gören tarafa gümüş veya mal cinsinden tazminat ödenmesi öngörülmüştür.'),
  ('Hitit İmparatorluk Çağı\'nda hem başkomutan hem başyargıç olan hükümdarın, yılın belirli aylarında askeri seferini bile yarıda bırakarak başkente dönmesinin nedeni nedir?', 'Başrahip sıfatıyla ulusal dini bayramları bizzat yönetme zorunluluğu', ['Eyalet valilerinin topladığı yıllık vergileri yerinde sayma geleneği', 'Pankuş üyelerinin her bahar yenilenen güven oylamasına katılma şartı', 'Yabancı tüccar loncalarının ticaret izinlerini mühürleme yükümlülüğü'], 'Hitit kralı aynı zamanda başrahiptir; dini törenleri aksatmanın tanrıların gazabını çekeceğine inanıldığından büyük bayramları bizzat yönetirdi.'),
  ('Urartu devlet inancında ordunun önünde sefere çıktığına inanılan, adına kalkanlar ve silahlar adanan savaşçı baş tanrı aşağıdakilerden hangisidir?', 'Haldi', ['Teşup', 'Şamaş', 'Marduk'], 'Haldi, Urartu panteonunun en üstünde yer alan savaş ve devlet tanrısıdır; krallar seferlerini Haldi\'nin adıyla başlatırlardı.'),
  ('Erzincan yakınlarındaki Altıntepe ve Van Gürpınar\'daki Çavuştepe kazılarında ortaya çıkarılan Urartu kalelerinde ortak olarak gözlenen mimari birimlerden biri aşağıdakilerden hangisidir?', 'Erzakların dev küpler içinde saklandığı çok sayıda depo odası', ['Halkın tiyatro oyunlarını izlediği yarım daire taş amfiler', 'Atlı araba yarışlarının düzenlendiği sütunlu hipodrom pistleri', 'Pişmiş toprak borularla ısıtılan mermer kubbeli halk hamamları'], 'Urartu kalelerinde tahıl, şarap ve susam yağı gibi ürünlerin dev pithos küplerinde depolandığı büyük ambarlar saray ekonomisinin merkezini oluştururdu.'),
  ('Konya\'nın Ereğli ilçesi yakınlarında kayaya oyulmuş olup Kral Warpalawas\'ı bereket tanrısı Tarhunzas karşısında üzüm salkımı ve buğday başaklarıyla betimleyen Geç Hitit eseri hangisidir?', 'İvriz Kaya Kabartması', ['Karabel Geçidi Anıtı', 'Yazılıkaya On İki Tanrı Rölyefi', 'Behistun Zafer Kitabesi'], 'İvriz Kaya Kabartması, Geç Hitit (Tuwana Krallığı) dönemine ait, tarım ve bereket temasını işleyen ünlü anıtsal kabartmadır.'),
  ('MÖ 1200 dolaylarında Ege Göçleri (Deniz Kavimleri) sonucunda Hattuşa\'daki merkezi Hitit İmparatorluğu yıkıldıktan sonra Hitit kültür ve siyasi geleneği hangi bölgede varlığını sürdürmüştür?', 'Güneydoğu Anadolu ve Kuzey Suriye\'deki Geç Hitit şehir devletlerinde', ['Batı Karadeniz kıyılarındaki denizci ticaret kolonilerinde', 'Doğu Karadeniz dağlarının yüksek yayla kalelerinde', 'Trakya yarımadasındaki tahkimli kabile yerleşimlerinde'], 'Merkezi Hitit Devleti yıkılınca Kargamış, Malatya, Zincirli (Sam\'al) ve Karatepe gibi Geç Hitit beylikleri kültürü MÖ 8. yüzyıla dek yaşatmıştır.'),
  ('Hitit ordusunun Kadeş Savaşı\'nda Mısır birliklerine ani baskın yapabilmesini sağlayan ve her birinde sürücü, kalkan taşıyıcı ile mızrakç olmak üzere üç askerin bulunduğu savaş aracı hangisidir?', 'Üç kişilik hafif savaş arabası', ['Demir zırhlı koçbaşı kulesi', 'Dört kürekli nehir kadırgası', 'Uzun menzilli taş mancınığı'], 'Mısır savaş arabaları iki kişilikken, Hititler bir sürücü, bir kalkanlı koruyucu ve bir hücumcudan oluşan üç kişilik savaş arabalarıyla üstünlük kurmuşlardır.'),
  ('Urartu krallarının fethettikleri ovalarda yerli nüfusu ve savaş esirlerini yeni kurdukları kalelerin çevresindeki tarım arazilerine planlı biçimde yerleştirmelerinin temel ekonomik amacı nedir?', 'Sulama kanallarıyla açılan verimli arazilerde tarımsal üretimi ve vergi gelirini artırmak', ['Asur tüccarlarının Doğu Anadolu\'ya girmesini tamamen yasaklamak', 'Göçebe hayvancılığı tasfiye ederek yalnızca deniz ticaretine yönelmek', 'Tapınak kölelerinden oluşan bağımsız şehir cumhuriyetleri kurmak'], 'Urartular iskân siyasetiyle iş gücünü yeni baraj ve kanalların suladığı ovalara yönlendirerek tahıl ve bağcılık üretimini büyütmüşlerdir.'),
  ('Van\'ın doğusundaki Erek Dağı eteklerinde Urartu Kralı II. Rusa tarafından yapay bir baraj gölü olarak inşa edilen ve tarım arazilerini sulamada kullanılan yapı hangisidir?', 'Keşiş Gölü', ['Tuz Gölü Regülatörü', 'Beyşehir Taş Köprüsü', 'Bafa Su Kapanı'], 'II. Rusa\'nın yüksek rakımda bentlerle kurduğu Keşiş Gölü, antik dünyanın en gelişmiş baraj ve su depolama sistemlerinden biridir.'),
  ('MÖ 14. yüzyılda Mitanni Devleti\'ni etkisizleştirip Kuzey Suriye\'yi hakimiyet altına alarak Hitit Devleti\'ni Yakın Doğu\'nun süper gücü (imparatorluk) konumuna yükselten hükümdar kimdir?', 'I. Şuppiluliuma', ['Anitta', 'Labarna', 'II. Sarduri'], 'I. Şuppiluliuma gerçekleştirdiği başarılı seferlerle Mitanni gücünü kırmış ve Hitit İmparatorluk Çağı\'nın en parlak temellerini atmıştır.'),
  ('MÖ 8. yüzyılın son çeyreğinde Kuzeyden Kafkaslar üzerinden Anadolu\'ya giren hangi savaşçı göçebe topluluk hem Urartulara ağır darbeler vurmuş hem de bölgenin siyasi dengesini sarsmıştır?', 'Kimmerler ve İskitler', ['Dorlar ve Akalar', 'Gotlar ve Vandallar', 'Amoriler ve Elamlar'], 'Kafkaslar üzerinden gelen Kimmer ve ardından İskit akınları Urartu kalelerinin tahrip olmasına ve devletin zayıflayıp yıkılmasına zemin hazırlamıştır.'),
  ('Beyşehir Gölü yakınlarında yer alan, kutsal bir su havuzunun kenarında gök kubbeyi taşıyan dağ ve boğa adam kabartmalarıyla ünlü Hitit su anıtı hangisidir?', 'Eflatunpınar Anıtı', ['Yazılıkaya Nekropolü', 'Meher Kapısı', 'Malabadi Çeşmesi'], 'Konya Beyşehir\'deki Eflatunpınar Hitit Su Anıtı, doğal kaynak suyunun toplandığı havuz ve kozmolojik taş kabartmalarıyla eşsiz bir kutsal alandır.'),
  ('Hitit Devleti\'nin Asur, Babil ve Mısır krallarıyla yaptığı resmi diplomatik yazışmalarda kendi dili olan Hititçe yerine genellikle hangi uluslararası diplomasi dilini kullanması dönemin etkileşimini gösterir?', 'Akadca', ['Aramice', 'Fenikece', 'Grekçe'], 'Tunç Çağı Yakın Doğu dünyasında uluslararası diplomasi dili Akadca olduğu için Kadeş Antlaşması dahil dış yazışmalar Akadca kil tabletlere yazılmıştır.'),
  ('MÖ 9. yüzyıldan itibaren Doğu Anadolu\'daki Nairi ve Uruatri konfederasyonlarının birleşerek güçlü bir merkezi Urartu Krallığı kurmalarını hızlandıran dış tehdit hangisidir?', 'Yeni Asur İmparatorluğu\'nun hammadde ve ganimet amaçlı yağma seferleri', ['Mısır ordularının Fırat Nehri\'ni aşarak kuzeye ilerlemesi', 'Pers satraplıklarının Kafkas geçitlerini vergiye bağlaması', 'Makedonya falankslarının Anadolu içlerine doğru yayılması'], 'Güneydeki Asur Devleti\'nin maden ve at ele geçirmek amacıyla düzenlediği aralıksız askeri seferler, yerel boyların Urartu çatısı altında birleşmesini sağlamıştır.'),
  ('Hitit toprak düzeninde devlete ait arazilerin bir bölümünün saray görevlilerine veya askerlere belirli bir hizmet ve vergi yükümlülüğü karşılığında işletilmek üzere verilmesi neyi gösterir?', 'Tımar benzeri hizmet karşılığı toprak tasarruf sisteminin erken örneklerinin uygulandığını', ['Ülkedeki tüm tarım arazilerinin özel mülkiyet senetleriyle alınıp satıldığını', 'Köylülerin hiçbir vergi ödemeden ürünün tamamına sahip olduğunu', 'Toprağın yalnızca yabancı tüccar loncaları tarafından kiralanabildiğini'], 'Hititlerde krala ait toprakların askerlik veya zanaat hizmeti karşılığında kişilere tahsis edilmesi (Şahhan ve Luzzi yükümlülükleri) feodal/tımar benzeri bir sistemdir.'),
  ('Hitit panteonunda baş tanrı konumundaki Fırtına Tanrısı Teşup\'un eşi olan ve metinlerde \'Arinna\'nın Güneş Tanrıçası\' olarak yüceltilen tanrıça hangisidir?', 'Hepat', ['İştar', 'Artemis', 'İsis'], 'Hurri-Hitit panteonunun birleşmesiyle Fırtına Tanrısı Teşup ve eşi Güneş Tanrıçası Hepat (Arinna) devletin baş tanrı çifti olarak kabul edilmiştir.'),
  ('Malatya yakınlarındaki Arslantepe Höyüğü, Hitit İmparatorluğu yıkıldıktan sonra hangi dönemin önemli başkentlerinden biri olarak anıtsal kral heykelleri ve kabartmalarıyla yeniden yükselmiştir?', 'Geç Hitit Krallıkları (Melid) dönemi', ['Erken Urartu Beylikleri dönemi', 'Lidya Altın Çağı dönemi', 'İyonya Deniz Kolonileri dönemi'], 'Kalkolitik ve Tunç Çağı\'nda önemli bir merkez olan Arslantepe (Melid), Demir Çağı\'nda Geç Hitit devletlerinden birinin başkenti olmuştur.'),
  ('Hitit sanatında tanrı ve kral kabartmalarının yüz ve ayaklarının profilden, gövde ve omuzlarının ise cepheden gösterilmesi hangi uygarlık havzasının estetik etkisiyle açıklanır?', 'Mezopotamya ve Mısır kabartma sanatı gelenekleriyle kurulan kültürel etkileşim', ['Ege adalarındaki natüralist mermer heykelcilik ekolünün doğrudan kopyalanması', 'Orta Asya bozkır kurganlarındaki hayvan üslubunun taş yüzeylere aktarılması', 'Roma zafer taklarındaki derin perspektif kurallarının erken dönemde uygulanması'], 'Hitit kabartmalarında gövdenin cepheden, baş ve ayakların profilden betimlenmesi Mısır ve Mezopotamya Yakın Doğu sanat kurallarının Anadolu\'daki yansımasıdır.'),
  ('Hitit Devleti\'nde veba salgınlarının yaklaşık yirmi yıl boyunca nüfusu kırıp geçirmesi üzerine Kral II. Murşili\'nin tanrılara yakarmak için yazdırdığı metinler edebiyat ve tarih açısından ne adla bilinir?', 'Veba Duaları', ['Gılgamış Ağıtları', 'Yaratılış İlahileri', 'Kadeş Şiirleri'], 'Mısır esirleriyle Anadolu\'ya taşınan salgın üzerine II. Murşili\'nin kaleme aldırdığı \'Veba Duaları\', Hitit din ve edebiyatının en özgün belgelerindendir.'),
  ('Hitit çömlekçiliğinde pişmiş topraktan parlak kırmızı astarlı olarak üretilen, özellikle dini törenlerde tanrılara sıvı sunusu (libasyon) yapmak için kullanılan boğa veya aslan biçimli kaplara ne ad verilir?', 'Riton (hayvan biçimli tören kabı)', ['Amfora (çift kulplu taşıma testisi)', 'Lekythos (zeytinyağı koku şişesi)', 'Krater (şarap su karıştırma teknesi)'], 'Hitit kült törenlerinde tanrılara içki sunmak için kullanılan hayvan başı ya da tam gövdesi şeklindeki kaplara \'riton\' (bibru) denir.'),
  ('Urartu kemerleri üzerinde kabartma tekniğiyle işlenen av sahneleri, savaş arabaları, kanatlı cinler ve kale kuşatmaları tarihçilere öncelikle hangi konuda görsel kanıt sunar?', 'Urartu soylularının askeri donanımı, saray ritüelleri ve mitolojik dünyası', ['Ege Denizi\'ndeki balıkçılık teknikleri ve ticaret gemisi türleri', 'Halk meclislerindeki gizli oylama ve seçim sandığı uygulamaları', 'Çivi yazısının harf alfabesine dönüşüm aşamalarının kronolojisi'], 'Geniş tunç Urartu kemerleri üzerindeki öyküleyici sahneler; giyim, silahlar, araba tipleri ve dini mitoloji hakkında eşsiz görsel belgelerdir.'),
  ('Urartu kalelerinin hemen eteklerinde soylu olmayan zanaatkârların, çiftçilerin ve tüccarların yaşadığı aşağı şehir yerleşimlerinin kurulması hangi toplumsal gelişmeye işaret eder?', 'Kale-saray ekseninden gerçek kentsel yerleşim dokusuna doğru evrilmeye', ['Merkezi krallık otoritesinin tamamen çöküp göçebeliğe dönülmesine', 'Askeri savunma ihtiyacının ortadan kalkarak surların yıkılmasına', 'Tüm halkın vergi muafiyeti kazanarak soylu sınıfına yükselmesine'], 'Başlangıçta yalnızca yönetici kalelerinden ibaret görünen Urartu merkezlerinin eteklerinde MÖ 8-7. yüzyıllarda planlı dış kentlerin büyümesi kentleşmeyi gösterir.'),
  ('Hitit kanunlarında bir kişinin başkasının kolunu ya da ayağını kırması hâlinde hem yaralanan kişiye gümüş ödenmesi hem de hekim masrafının karşılanıp iyileşene dek yerine çalışacak bir işçi verilmesi neyi amaçlar?', 'Mağdurun uğradığı iş gücü ve ekonomik kaybı bütünüyle telafi etmeyi', ['Suçluyu ömür boyu tapınak kölesi statüsüne düşürerek dışlamayı', 'Hekimlik mesleğini yalnızca saray görevlilerinin tekeline bırakmayı', 'Aileler arasında kan davası güdülmesini yasal bir hak haline getirmeyi'], 'Hitit hukuku intikam almaktan ziyade bozulan toplumsal ve ekonomik düzeni onarmayı, mağdurun üretim kaybını gidermeyi hedeflemiştir.'),
  ('Urartuların Doğu Anadolu\'da bağcılığa büyük önem verdiklerini ve şarap üretiminin devlet kontrolünde yürütüldüğünü kanıtlayan en somut arkeolojik buluntu hangisidir?', 'Üzerinde kapasite ölçüleri çivi yazısıyla belirtilmiş yüzlerce litrelik pithos küpleri', ['Göl tabanında bulunan tunç kaplamalı balıkçı teknelerinin çapaları', 'Kaya mezarlarına bırakılan fildişi satranç tahtaları ve zarları', 'Sınır taşlarına kazınmış güneş saati ve takvim çizelgeleri'], 'Karmir-Blur, Çavuştepe ve Altıntepe mahzenlerinde bulunan, üzerlerinde \'aruzi\' ve \'terusi\' sıvı ölçü birimleri yazılı dev küpler devlet şarap mahzenlerini kanıtlar.'),
  ('Hitit mitolojisinde öfkelenerek ortadan kaybolduğunda yeryüzünde kuraklık, açlık ve kısırlığın başladığına; arı tarafından bulunup öfkesi yatıştırıldığında ise bereketin geri döndüğüne inanılan tanrı kimdir?', 'Telepinu', ['Kumarbi', 'İlluyanka', 'Ullikummi'], 'Kaybolan Tanrı mitinin başkahramanı olan Tarım ve Bereket Tanrısı Telepinu\'nun gidişi kış ve kıtlığı, dönüşü ise bahar ve bolluğu simgeler.'),
  ('Hitit İmparatorluk Çağı\'nda kralın \'Benim Güneşim\' unvanını kullanmaya başlaması ve öldükten sonra \'tanrı olduğu\' ifadesinin metinlerde yer alması yönetim anlayışında neyin değiştiğini gösterir?', 'Soylular meclisinin etkisinin azalıp teokratik-mutlak monarşi gücünün pekiştiğini', ['Kralın dünyevi tüm askeri yetkilerini başkomutana devrederek inzivaya çekildiğini', 'Ülkedeki çok tanrılı inancın kaldırılıp yalnızca Güneş kültünün zorunlu kılındığını', 'Hükümdarların halk oylamasıyla belirli bir süre için iş başına getirildiğini'], 'Eski Krallık\'ta eşitler arası birinci gibi görülen kral, İmparatorluk devrinde Mısır ve Mezopotamya etkisiyle karizmatik, mutlak ve yarı-kutsal bir otoriteye dönüşmüştür.'),
  ('Hitit ordusuna ve zanaatına demir işlemeciliğinin sağladığı ayrıcalığı gösteren, III. Hattuşili\'nin bir yabancı krala mektubunda \'Kizzuvatna\'daki mühürlü evimde iyi demir kalmadı, üretilince göndereceğim\' demesi neyi kanıtlar?', 'Kaliteli demir üretiminin devlet tekelinde tutulan stratejik ve değerli bir meta olduğunu', ['Anadolu\'daki tüm demir yataklarının Tunç Çağı ortasında tamamen tükendiğini', 'Hititlerin demir silah yapımını öğrenmek için dışarıdan usta ithal ettiğini', 'Demirin sikkelerde altın ve gümüşten daha düşük değerli bozuk para sayıldığını'], 'Tunç Çağı\'nda ergitilmesi güç olan demir, Hitit sarayının denetiminde yüksek prestijli ve diplomatik hediye değerinde stratejik bir maden olarak korunmuştur.'),
  ('Çorum Alacahöyük\'teki Hitit dönemi Sfenksli Kapı\'nın yan bloklarında kabartma olarak betimlenen kılıç yutan akrobatlar ve merdivene tırmanan hokkabaz sahnesi neyi belgeler?', 'Dini bayramların müzik, dans ve seyirlik gösterilerle şenlik havasında kutlandığını', ['Yabancı casusların kent kapısında ağır işkencelerle sorguya çekildiğini', 'Acemi askerlerin orduya alınmadan önce denge sınavından geçirildiğini', 'Sirk oyunlarının köle tüccarları tarafından gelir amacıyla düzenlendiğini'], 'Alacahöyük ortostatlarındaki saz çalan müzisyenler, kılıç yutan ve merdivene çıkan akrobatlar, Hitit dini bayramlarındaki şenlik ve gösteri kültürünü yansıtır.'),
  ('Urartu sanatında saray duvarlarını süsleyen mavi, kırmızı ve siyah renkli fresklerde sıklıkla tekrarlanan kutsal hayat ağacının iki yanında duran kanatlı varlıklar hangi temayı simgeler?', 'Doğanın yenilenmesini, bereketi ve ilahi korumayı', ['Deniz aşırı sömürge seferlerinde kazanılan zaferleri', 'Yer altı mahkemesinde günahkâr ruhların tartılmasını', 'Dört mevsim boyunca uygulanan gümrük tarifelerini'], 'Altıntepe ve Erebuni duvar resimlerindeki hayat ağacını dölleyen/kutsayan kanatlı cinler, bolluk ve krallığın ilahi himayesini temsil eder.'),
  ('Muş\'un Varto ilçesindeki Kayalıdere ve Bingöl Solhan yolundaki Zulümtepe kalıntıları, Urartu Devleti\'nin batı yönündeki hangi faaliyetinin kanıtıdır?', 'Murat Nehri vadisi boyunca uzanan askeri ve ticari ulaşım hattını kontrol altına alma', ['Ege Denizi\'ne inerek İyon şehir devletleriyle donanma ittifakı kurma', 'Orta Anadolu\'daki tuz göllerinden mavnalarla başkent Tuşpa\'ya tuz taşıma', 'Karadeniz kıyılarında zeytinlikler kurarak yağ ihracatını başlatma'], 'Urartular batıya doğru Fırat-Murat vadisi boyunca kaleler ve yol istasyonları inşa ederek Malatya (Melid) ve maden havzalarına ulaşımı denetlemişlerdir.'),
  ('Urartu krallarının Asur\'a karşı batıdaki Geç Hitit şehir devletleri ve Friglerle diplomatik ittifaklar aramasının temel jeopolitik nedeni aşağıdakilerden hangisidir?', 'Kuzey Suriye ve Akdeniz limanlarına açılan ticaret yollarında Asur kuşatmasını kırmak', ['Mısır piramitlerinin yapımında çalışacak taş ustalarını Anadolu\'dan toplamak', 'Balkanlar üzerinden gelen Kelt kabilelerini Fırat boylarına yerleştirmek', 'Karadeniz\'deki Yunan kolonilerinden savaş fili satın alabilmek'], 'II. Sarduri ve I. Rusa gibi Urartu kralları, Asur\'un maden ve Akdeniz ticareti üzerindeki baskısını dengelemek için Geç Hitit ve Friglerle iş birliği yapmıştır.'),
  ('Hititlerin başkenti Hattuşa\'daki Büyük Tapınak (Tapınak 1) planında kutsal odaların çevresini kuşatan onlarca dar uzun koridor odanın varlığı tapınağın hangi ek işlevini kanıtlar?', 'Ülke ekonomisinin vergi, tahıl, maden ve tablet arşivi merkezi olarak da çalışmasını', ['Kuşatma anında yüz bin kişilik tüm kırsal nüfusun konut ihtiyacını karşılamasını', 'Yabancı gladyatörlerin vahşi hayvanlarla dövüştürüldüğü zindanlar barındırmasını', 'Yalnızca astronomi gözlemleri için karanlık optik tüneller olarak tasarlanmasını'], 'Hattuşa Büyük Tapınak, ibadet alanı olmasının yanında çevresindeki seksen küsur depo odasıyla dev bir iktisadi merkez ve devlet arşivi işlevi görmüştür.'),
  ('Hititlerin Hurrilerden devralarak kendi edebiyatlarına kazandırdıkları, gökyüzü krallığı için tanrı kuşakları arasındaki mücadeleyi anlatan ünlü mitolojik destan dizisi hangisidir?', 'Kumarbi Efsanesi', ['İlyada Destanı', 'Ergenekon Destanı', 'Şehname Mesnevisi'], 'Anu, Kumarbi ve Fırtına Tanrısı Teşup arasındaki gökyüzü egemenliği mücadelesini işleyen Hurri kökenli Kumarbi mitosu, Yunan Theogonia\'sını da etkilemiştir.'),
  ('Urartuların son dönemlerinde Kral II. Rusa\'nın eski başkent Tuşpa\'nın hemen kuzeyindeki sarp tepeye kurduğu ve ilk bilimsel Urartu kazılarının da yapıldığı merkez hangisidir?', 'Toprakkale (Rusahinili)', ['Kültepe (Kaniş)', 'Boğazköy (Hattuşa)', 'Hisarlık (Troya)'], 'II. Rusa\'nın kurduğu Rusahinili (Toprakkale), 19. yüzyıl sonlarında yapılan kazılarla Urartu uygarlığının bilim dünyasında tanınmasını sağlayan ilk merkezdir.'),
  ('Urartu savunma mimarisinde kale surlarının düz bir hat yerine belirli aralıklarla dışa taşkın payanda ve burçlarla (kurtin-bastiyon sistemi) inşa edilmesinin askeri amacı nedir?', 'Sur dibine yaklaşan düşman askerlerini yanlardan çapraz ok ateşine alabilmek', ['Deprem dalgalarını kale içine yönlendirerek yer altı sularını çıkarmak', 'Güneş ışığının gölgesiyle günün saatlerini sur üzerinde hesaplamak', 'Yabancı kervanların develerini bağlayabileceği gölgelik bölmeler oluşturmak'], 'Urartu surlarındaki sık aralıklı çıkıntı ve burçlar hem duvarın statik dayanıklılığını artırmış hem de kuşatmacılara karşı yan ateş üstünlüğü sağlamıştır.'),
  ('Kadeş Antlaşması\'nın içeriğinde yer alan \'Bir ülkeden kaçıp diğerine sığınan siyasi suçlular iade edilecek ancak kendilerine ölüm ya da sakatlama cezası verilmeyecektir\' maddesi modern hukuktaki hangi ilkenin öncülüdür?', 'Suçluların iadesi ve insani güvence şartı', ['Diplomatik kuryelerin gümrükten muaf tutulması', 'Uluslararası açık denizlerde serbest seyrüsefer hakkı', 'Tarafsız devletlerin savaşta arabuluculuk yetkisi'], 'Kadeş Antlaşması karşılıklı ittifak ve saldırmazlık yanında mültecilerin/suçluların iadesini ve iade edilenlerin yaşam hakkının korunmasını düzenlemiştir.'),
  ('Karadeniz bölgesinde yaşayarak Hitit başkenti Hattuşa\'ya sık sık baskınlar düzenleyen, Hitit krallarını kuzey sınırında sürekli savunma kaleleri kurmaya zorlayan yarı göçebe kavim hangisidir?', 'Kaşkalar', ['Fenikeliler', 'Sümerler', 'Lidyalılar'], 'Kuzey Anadolu dağlarında yaşayan savaşçı Kaşka boyları, Hitit tarihi boyunca devletin kuzey sınırını tehdit etmiş ve hatta zaman zaman Hattuşa\'yı yağmalamıştır.'),
  ('Ankara\'nın Polatlı ilçesi yakınlarındaki Gordion antik kentinde kazılan yığma toprak tepelerin (tümülüs) içindeki mezar odalarının binlerce yıl çökmeden kalmasını sağlayan yapı malzemesi nedir?', 'Ardıç ve sedir tomruklarından birbirine geçmeli kurulan ahşap oda sistemi', ['Pişmiş tuğla ve horasan harcıyla örülen yüksek sivri kemerli kubbeler', 'Eritilmiş kurşun kenetlerle tutturulan tek parça beyaz mermer bloklar', 'Saz kamışları ve zift karışımıyla sıkıştırılan güneşte kurutulmuş kerpiçler'], 'Frig tümülüslerinde (özellikle Büyük Tümülüs/Midas Tümülüsü) çürümesi çok zor olan ardıç ve çam/sedir kütükleriyle harçsız inşa edilen ahşap mezar odaları günümüze sağlam ulaşmıştır.'),
  ('Frig dokumacılarının yün ve keçi kılından ürettikleri, geometrik motifleriyle antik dünyada büyük ün kazanan ve Gordion mezarlarında örneklerine rastlanan halı-kilim türüne ne ad verilmiştir?', 'Tapates', ['Fibula', 'Megaron', 'Kiton'], 'Friglerin ürettiği çift yüzlü ve zengin geometrik desenli \'tapates\' adlı dokuma yaygı ve kilimler Türk halı-kilim sanatındaki motiflerle de benzerlik taşır.'),
  ('Teke Yarımadası\'nda (Antalya-Fethiye arası) kurulan Likya Birliği\'nin Patara kentindeki meclis yapısını antik dünyanın ilk demokratik federasyon modeli kılan uygulama hangisidir?', 'Üye şehirlerin büyüklüklerine göre bir, iki ya da üç oy hakkıyla mecliste orantılı temsil edilmesi', ['Birlik başkanının ömür boyu görev yapmak üzere en yaşlı tapınak rahibinden seçilmesi', 'Yalnızca kıyıdaki liman kentlerine oy hakkı tanınıp dağ kentlerinin vergiye bağlanması', 'Tüm kararların Pers satrapının yazılı onayı olmadan yürürlüğe girememesi'], '23 kentten oluşan Likya Birliği\'nde Ksantos, Patara, Myra gibi büyük kentler 3 oy, orta kentler 2, küçükler 1 oy kullanır ve vergi/asker yükünü de aynı oranda paylaşırdı.'),
  ('Muğla ve çevresini kapsayan Karya bölgesinin satrabı Mausolos için başkent Halikarnas\'ta (Bodrum) inşa edilen ve Antik Dünyanın Yedi Harikası\'ndan biri sayılan anıt mezarın mimari özelliği nedir?', 'Yunan sütunlu tapınak cephesi ile Mısır basamaklı piramit çatısını birleştirmesi', ['Tamamen kaya içine oyularak yer altında üç katlı labirent şeklinde tasarlanması', 'Pişmiş topraktan sırlı çinilerle kaplı sekizgen bir kümbet gövdesine sahip olması', 'Denizin ortasındaki yapay bir adacık üzerine tunç sütunlarla dikilmiş olması'], 'Pytheos ve Satyros\'un tasarladığı Halikarnas Mozolesi, yüksek kaide üzerinde İyon sütunları ve tepesinde dört atlı araba heykeli taşıyan piramidal çatısıyla sentez bir yapıdır.'),
  ('Eskişehir-Afyon-Kütahya üçgenindeki Dağlık Frigya bölgesinde yer alan, üçgen alınlıklı ve geometrik cephe bezemeli en görkemli açık hava kaya anıtı aşağıdakilerden hangisidir?', 'Yazılıkaya Midas Anıtı', ['İvriz Bereket Anıtı', 'Karabel Savaşçı Rölyefi', 'Behistun Kaya Yazıtı'], 'Eskişehir\'in Han ilçesi sınırlarındaki Yazılıkaya (Midas Kenti), kayaya oyulmuş anıtsal megaron cephesi ve Frigce yazıtıyla Dağlık Frigya\'nın başyapıtıdır.'),
  ('İyonya şehir devletlerinden Miletos ve Phokaia\'nın (Foça) MÖ 8. ve 6. yüzyıllar arasında Karadeniz ile Batı Akdeniz kıyılarında onlarca koloni kenti kurmalarının başlıca jeopolitik nedeni nedir?', 'Artan nüfusa tarım alanı bulmak, hammadde kaynaklarına ulaşmak ve arka bölgedeki Lidya baskısını aşmak', ['Tüm Anadolu içlerini askeri imparatorluk çatısı altında tek merkezden yönetmek', 'Mısır firavunlarının emriyle Cebelitarık dışındaki okyanus adalarını haritalamak', 'İpek Yolu\'nun Çin\'deki başlangıç noktasını doğrudan denizden ele geçirmek'], 'İyon kentlerinin dar kıyı şeridi ve içeride Lidya Krallığı\'nın genişlemesi, Milet\'i Karadeniz\'de (Sinop, Trabzon, Amasra), Foça\'yı ise Batı Akdeniz\'de (Marsilya, Korsika) kolonizasyona yöneltmiştir.'),
  ('Likya antik kentlerinde (Ksantos, Myra, Tlos) sarp yamaçlara oyulmuş kaya mezarlarının cephelerinde ahşap kiriş uçlarının ve çatkı sisteminin taş üzerinde taklit edilmesi neyi kanıtlar?', 'Bölgedeki geleneksel sivil ahşap konut mimarisinin mezar sanatına yansıtıldığını', ['Likyalıların taş yontma aletlerini dışarıdan ithal etmek zorunda kaldığını', 'Mezarların aynı zamanda tahıl kurutma ambarı olarak kullanıldığını', 'Pers valilerinin tüm mezarların tek tip askeri kışla gibi yapılmasını emrettiğini'], 'Likya\'nın \'ev tipi kaya mezarları\' ve ters kayık kapaklı lahitleri, Likyalıların ahşap karkaslı ev mimarisini ölülerin ebedi evi olan taş mezarlara birebir aktardığını gösterir.'),
  ('Gordion sitadelinde ortaya çıkarılan, önde giriş sundurması ve arkasında ortası ocaklı büyük salondan oluşan dikdörtgen planlı yapı tipine antik mimaride ne ad verilir?', 'Megaron', ['Bazilika', 'Peristil', 'Apadana'], 'Batı Anadolu\'da Troya\'dan beri bilinen ve Friglerin başkent Gordion\'da saray ve idari binalar olarak anıtsal ölçekte uyguladıkları yapı tipi \'megaron\'dur.'),
  ('Herodot\'un aktardığına göre Pers komutanı Harpagos MÖ 540\'larda Likya\'nın başkenti Ksantos\'u kuşattığında kent halkının esir düşmemek için sergilediği tavır ne olmuştur?', 'Ailelerini ve hazinelerini kaleye toplayıp ateşe verdikten sonra son ferdine kadar savaşarak ölmek', ['Tüm gemilere binerek Karadeniz\'in kuzey kıyılarındaki kolonilere sığınmak', 'Kral Yolu\'nun haritasını Perslere teslim ederek vergi muafiyeti satın almak', 'Komşu Karya şehirleriyle birleşip başkenti Halikarnas\'a taşımak'], 'Özgürlüklerine düşkünlüğüyle tanınan Ksantos halkı hem Pers kuşatmasında hem yüzyıllar sonra Roma komutanı Brutus kuşatmasında teslim olmak yerine toplu direnişi seçmiştir.'),
  ('Friglerin Yunan harf sistemine dayanan Fenike kökenli alfabeyi MÖ 8. yüzyılda kendi Hint-Avrupa dillerine uyarlayarak taş anıtlar ve balmumu levhalar üzerinde kullanmaları neyi gösterir?', 'Anadolu\'da çivi yazısı geleneğinden fonetik harf alfabesine geçişin öncülerinden olduklarını', ['Yazıyı yalnızca gizli büyü formüllerinde kullanan kapalı bir rahip devleti kurduklarını', 'Yunan şehir devletlerini vergiye bağlayarak kendi dillerini zorla öğrettiklerini', 'Kil tablet arşivciliğini Hititlerden daha geniş ölçekte sürdürdüklerini'], 'Tunç Çağı sonunda çivi yazısı unutulduktan sonra Anadolu\'da Demir Çağı\'nda harf yazısını benimseyip kaya anıtlarına ve kaplara kazıyan ilk büyük uygarlıklardan biri Friglerdir.'),
  ('Manisa\'nın Salihli ilçesi yakınlarında Gediz Ovası\'nda yer alan ve Lidya kralları (Alyattes, Gyges) ile soylularına ait yüzden fazla yığma mezar tepesini barındıran nekropol alanı hangisidir?', 'Bintepeler', ['Yazılıkaya', 'Çatalhöyük', 'Göbeklitepe'], 'Marmara Gölü ile Salihli arasındaki Bintepeler nekropolü, özellikle Kral Alyattes\'in devasa tümülüsüyle Anadolu\'nun en büyük tümülüs mezarlık alanıdır.'),
  ('Efesli filozof Herakleitos\'un \'Aynı ırmağa iki kez giremezsin; çünkü üzerinden yeni sular akmaktadır\' özdeyişi İyon doğa felsefesinde hangi temel görüşü savunur?', 'Evrendeki her varlığın sürekli bir oluş, değişim ve karşıtların çatışması içinde bulunduğunu', ['Doğadaki tüm olayların değişmez ve hareketsiz tek bir maddeden donmuş olduğunu', 'Duyularla algılanan fiziksel dünyanın tanrıların yarattığı bir göz yanılması olduğunu', 'İnsan bilgisinin yalnızca tapınak kâhinlerinin yorumlarıyla kesinliğe ulaşacağını'], 'Efesli Herakleitos evrenin ana ilkesini (arkhe) \'ateş\' ve \'logos\' olarak görmüş, sürekli akış ve değişim (panta rhei) öğretisini kurmuştur.'),
  ('Likya\'nın en önemli liman kenti Patara\'da Roma İmparatoru Neron döneminde dikilen deniz feneri ile İmparator Claudius döneminde dikilen \'Stadiasmus Patarensis\' adlı yol anıtı kentin hangi yönünü öne çıkarır?', 'Deniz ticareti güvenliği ile kara yolları ağının kesiştiği başlangıç noktası olmasını', ['Yalnızca gladyatör okullarının yetiştirildiği kapalı bir askeri garnizon olmasını', 'Anadolu\'da demir madeninin ilk kez eritildiği sanayi vadisi konumunda bulunmasını', 'Sadece din adamlarının yaşadığı dış dünyaya kapalı bir manastır kenti olmasını'], 'Patara hem Likya Birliği meclisinin merkezi ve ana dış ticaret limanı hem de Likya yol ağındaki tüm mesafeleri gösteren yol kılavuz anıtının dikildiği merkezdir.'),
  ('Müzik tarihinde çift borulu üflemeli çalgı olan \'aulos\' (flüt/kaval) ile üçgen telli çalgıların gelişiminde ve Yunan müziğindeki \'Frig makamı\'nın doğuşunda hangi Anadolu uygarlığının katkısı belirleyicidir?', 'Frigler', ['Urartular', 'Likyalılar', 'Kaşkalar'], 'Yunan mitolojisinde Marsyas ile Apollon arasındaki müzik yarışması efsanesine de konu olan flüt (aulos) ve coşkulu Frig modu Anadolu Frig kültürünün mirasıdır.'),
  ('Lidya\'nın başkenti Sardes\'te Roma dönemine dek genişleyerek yaşatılan, ancak temellerinde altın arıtma işlikleri ile pazar dükkânlarının yan yana dizildiği kentsel yapı özelliği neyi kanıtlar?', 'Perakende dükkân ticaretinin ve değerli maden zanaatının şehir merkezinde kurumsallaştığını', ['Şehir içinde her türlü ticaretin yasaklanıp pazarların kırsala taşındığını', 'Altın işlemeciliğinin yalnızca gezgin göçebe demirciler tarafından yapıldığını', 'Tapınak rahiplerinin sivil esnaftan zorla mülk müsadere ettiğini'], 'Herodot\'un da belirttiği üzere Lidyalılar tarihte sürekli perakende ticaret dükkânlarını (kapeloi) ve hanları kurumsallaştıran ilk topluluklardan biridir.'),
  ('MÖ 499 yılında Milet tiranı Aristagoras öncülüğünde başlayan ve Batı Anadolu\'daki şehirlerin Sardes\'i yakmasına kadar varan \'İyon Ayaklanması\' hangi imparatorluğun Anadolu hâkimiyetine karşı yapılmıştır?', 'Pers (Akhamenid) İmparatorluğu', ['Yeni Babil İmparatorluğu', 'Makedonya Krallığı', 'Roma Cumhuriyeti'], 'Perslerin ağır vergileri, ticari daralma ve şehirlere Pers yanlısı tiranlar atamasına tepki olarak patlak veren İyon İsyanı (MÖ 499-494), Pers-Yunan Savaşları\'nın da fitilini ateşlemiştir.'),
  ('İyon mimarlık düzenini (nizamını) Yunan anakarasındaki Dor düzeninden görsel olarak ayıran en belirgin sütun başlığı detayı nedir?', 'İki yana koç boynuzu veya parşömen rulosu gibi kıvrılan volütlü başlık', ['Hiçbir süsleme taşımayan düz, sade ve yastık biçimli taş tabla', 'Yalnızca lotus çiçeği ve papirüs demetlerinden oluşan Mısır başlığı', 'Sütun gövdesinin yerine insan heykellerinin taşıyıcı olarak konulması'], 'Batı Anadolu İyonya kentlerinde doğan İyon düzeni; ince yivli zarif gövdesi, kaidesi ve iki yana kıvrımlı \'volüt\' taşıyan sütun başlığıyla tanınır.'),
  ('Karya ile İyonya sınırına yakın Afrodisias, Mylasa (Milas) ve Alinda gibi kentlerin iç kesimlerle kıyı limanları arasında üstlendiği iktisadi rol nasıl özetlenebilir?', 'Dağlık bölgelerden elde edilen kereste, mermer, bal ve zeytinyağını kıyı ticaretine aktarma', ['Mezopotamya\'dan gelen kalay madenini eritip Asur ordusuna satma', 'Orta Asya\'dan gelen deve kervanlarına yalnızca kışlık konaklama sağlama', 'Karadeniz\'den avlanan tuzlu balıkları Mısır tapınaklarına ulaştırma'], 'Karya kentleri zengin mermer ocakları, çam kerestesi, incir, zeytinyağı ve şarap üretimiyle Ege deniz ticaretini besleyen verimli bir art bölge (hinterland) oluşturmuştur.'),
  ('Asur Kralı II. Sargon\'un yıllıklarında Güneydoğu Anadolu ve Kapadokya sınırında Urartularla ittifak kuran \'Muşki Kralı Mita\' olarak geçen hükümdar, Batı kaynaklarındaki hangi kral ile aynı kişidir?', 'Frig Kralı Midas', ['Lidya Kralı Gyges', 'Karya Kralı Mausolos', 'Hitit Kralı Murşili'], 'Doğu (Asur) kaynaklarının \'Muşki\' dediği toplulukla Batı (Yunan) kaynaklarının \'Frig\' dediği krallığın MÖ 8. yüzyıl sonundaki hükümdarı Mita/Midas birleşmiştir.'),
  ('Lidya süvari birliklerinin uzun mızraklarla hücum yeteneğinin antik dünyada ün kazanmasında başkent Sardes\'in içinde yer aldığı Gediz (Hermos) Ovası\'nın hangi özelliği etkili olmuştur?', 'Geniş çayırların nitelikli at yetiştiriciliğine ve süvari manevralarına çok elverişli olması', ['Sarp kanyonlarla bölünmüş arazinin yaya yürüyüşünü tamamen imkânsız kılması', 'Bölgede demir madeni bulunmadığı için piyade zırhı üretilememesi', 'Ovanın yılın dokuz ayı sular altında kalarak bataklık oluşturması'], 'Verimli Gediz Ovası\'nda yetiştirilen güçlü atlar sayesinde Lidya süvarileri MÖ 7.-6. yüzyıllarda Ön Asya\'nın en çekinilen atlı birlikleri arasında yer almıştır.'),
  ('Aydın Didim\'de bulunan ve Miletos kentine kutsal bir yolla bağlanan Didyma Apollon Tapınağı antik dünyada öncelikle hangi işleviyle tanınmıştır?', 'Kralların ve şehirlerin gelecek hakkında danıştığı büyük kehanet merkezi (bilicilik ocağı) olmasıyla', ['Akdeniz\'in en büyük tıp kütüphanesini ve şifalı çamur banyolarını barındırmasıyla', 'Olimpiyat oyunlarına katılacak atletlerin seçildiği tek stadyum olmasıyla', 'Lidya altınlarının saklandığı askeri merkez bankası olarak kullanılmasıyla'], 'Yunanistan\'daki Delfi\'den sonra antik dünyanın en ünlü kehanet merkezi İyonya\'daki Didyma Apollon Tapınağı\'ydı; Lidya Kralı Kroisos bile buraya danışmıştı.'),
  ('Likya\'daki Ksantos kentinde yükselen \'Harpy Anıtı\' ve \'Nereidler Anıtı\' gibi yüksek taş payeler veya tapınak cepheli kaideler üzerine yerleştirilmiş mezar yapıları kimler için inşa edilmiştir?', 'Likya kentlerini yöneten yerli hanedan beyleri (dinastlar) için', ['Deniz savaşlarında boğularak hayatını kaybeden kürekçi köleler için', 'Yalnızca başka ülkelerden gelip kentte vefat eden elçiler için', 'Olimpiyat yarışmalarında birinci gelen araba sürücüleri için'], 'MÖ 5.-4. yüzyıllarda Likya kentlerini yöneten yerli beyler (dinastlar), askeri başarılarını ve soyağaçlarını yücelten kabartmalı yüksek dikme ve tapınak-mezarlar yaptırmışlardır.'),
  ('Lidyalıların insanlık tarihine armağan ettiği sikke basımı incelendiğinde erken dönem Lidya paralarının ön yüzünde kral portresi yerine hangi hanedan armasının yer aldığı görülür?', 'Karşılıklı duran aslan ve boğa başı ya da kükreyen aslan protomu', ['Kanatlarını açmış çift başlı kartal ve hayat ağacı', 'Yedi kollu şamdan ile buğday başağı çelengi', 'Üç kürekli savaş kadırgası ve yunus balığı'], 'İlk Lidya sikkelerinde hükümdar portresi yoktur; Lidya kraliyet gücünü simgeleyen kükreyen aslan başı ya da yüz yüze bakan aslan-boğa (Kroisos sikkeleri) kabartması basılmıştır.'),
  ('Foçalı (Phokaia) denizcilerin MÖ 600 dolaylarında Fransa\'nın güney kıyısında kurdukları ve Batı Avrupa\'ya zeytin, üzüm tarımı ile yazı kültürünü taşıyan ünlü koloni kenti hangisidir?', 'Massalia (Marsilya)', ['Kartaca (Tunus)', 'Sinope (Sinop)', 'Trapezus (Trabzon)'], 'Anadolu\'nun İyon kenti Foça\'dan çıkan denizciler Akdeniz\'in batısında Massalia\'yı (bugünkü Marsilya) kurarak Galya içlerine Anadolu-Ege uygarlığını taşımışlardır.'),
  ('Miletli doğa filozofu Thales\'in Mısır\'a yaptığı gezide arazi ölçüm tekniklerini inceleyerek piramitlerin yüksekliğini gölge boyu yardımıyla hesaplaması hangi bilimsel gerçeği ortaya koyar?', 'İyon biliminin Doğu uygarlıklarının pratik bilgisini kuramsal geometriye dönüştürdüğünü', ['Mısırlıların geometri alanında hiçbir ölçüm yöntemi bilmediğini', 'İyon filozoflarının başka ülkelerle temas kurmaktan kaçındığını', 'Piramitlerin Miletli mimarlar tarafından tasarlanıp inşa edildiğini'], 'İyonya bilginleri Mısır\'ın pratik arazi ölçümü ve Babil\'in gökyüzü kayıtlarını öğrenmiş, ancak bunları genel teorem ve rasyonel doğa yasalarına dönüştürerek bilimi kurmuşlardır.'),
  ('Likya\'nın doğu sınırındaki Yanartaş (Khimaira) mevkiinde kayalıklardan doğal olarak sızıp sürekli yanan metan gazı alevleri, antik mitolojide hangi efsanenin doğmasına kaynaklık etmiştir?', 'Kahraman Bellerophontes\'in kanatlı atı Pegasus ile ateş saçan Khimaira canavarını yenmesi', ['Prometheus\'un tanrılardan ateşi çalarak Kafkas Dağları\'nda zincire vurulması', 'İkarus\'un balmumu kanatlarının Güneş\'e yaklaşınca eriyip denize düşmesi', 'Midas\'ın dokunduğu her nesnenin altına dönüşmesi üzerine Paktolos\'ta yıkanması'], 'Olympos yakınlarındaki sönmeyen doğal gaz ateşi, Likyalı kahraman Bellerophontes\'in aslan başlı, keçi gövdeli, yılan kuyruklu Khimaira\'yı toprağa gömdüğü mitini doğurmuştur.'),
  ('Lidya toplumunda krallık ekonomisinin yalnız altın madenlerine değil, aynı zamanda dokuma, parfüm/kozmetik (\'bakkaris\') ve dericiliğe dayanması Sardes\'e hangi niteliği kazandırmıştır?', 'Doğu ile Ege dünyası arasında lüks tüketim malları üreten bir sanayi ve moda merkezi olması', ['Yalnızca kaba tarım aletleri üreten dışa kapalı bir köylü kasabası olarak kalması', 'Sadece savaş esirlerinin çalıştırıldığı askeri tersane kenti niteliği taşıması', 'Hiçbir kervanın uğramadığı yüksek dağ manastırı hüviyetine bürünmesi'], 'Sardes; erguvan boyalı yünlü dokumaları, altın takıları ve \'bakkaris\' adlı kokulu merhemleriyle hem Yunan hem Pers soylularının özendiği lüks üretim merkeziydi.'),
  ('Friglerin MÖ 1200\'lerdeki Ege Göçleri sonrasında Balkanlar/Trakya üzerinden Anadolu\'ya gelip başlangıçta boylar hâlinde yaşadıktan sonra MÖ 9.-8. yüzyılda Gordion merkezli krallığa dönüşmesi nasıl açıklanır?', 'Orta Anadolu\'daki yerli Hatti-Hitit mirasıyla kaynaşarak yerleşik devlet düzenini benimsemeleriyle', ['Asur İmparatorluğu tarafından zorla Polatlı Ovası\'na sürgün edilmeleriyle', 'Denizcilikte başarısız olunca tüm gemilerini yakarak iç bölgeye çekilmeleriyle', 'Lidya sikkelerini basmak üzere ücretli maden işçisi olarak davet edilmeleriyle'], 'Balkan kökenli Brig/Frig boyları Kızılırmak ve Sakarya havzasında eski Hitit kültür alt yapısıyla birleşerek güçlü bir tarım krallığı ve özgün bir sanat kurmuşlardır.'),
  ('Amerika Birleşik Devletleri Anayasası\'nı hazırlayan kurucuların (özellikle Alexander Hamilton ve Montesquieu\'nün yazılarında) federal cumhuriyetin tarihteki en başarılı modeli olarak övdükleri Anadolu siyasi birliği hangisidir?', 'Likya Birliği', ['Hitit Pankuşu', 'İyon Panionionu', 'Urartu Krallığı'], 'Montesquieu \'Kanunların Ruhu\' adlı eserinde Likya Birliği\'ni \'Eğer kusursuz bir federal cumhuriyet örneği verecek olsaydım Likya\'yı gösterirdim\' diyerek övmüş, bu model ABD anayasasına esin vermiştir.'),
  ('Frigçe kaya yazıtlarında mezarlara ya da kutsal anıtlara zarar verecek kişilere karşı sıkça tekrarlanan \'Toprak ve su ona verimli olmasın, tanrıça onu cezalandırsın\' içerikli cümleler ne amaçla yazılmıştır?', 'Hukuki yaptırımı dinsel beddua formülleriyle destekleyerek anıt tahribatını ve mezar soygununu önlemek', ['Kuraklık dönemlerinde rahiplerin okuyacağı yağmur duasını halka ezberletmek', 'Tarım arazilerinin sınırlarını belirleyen kadastro ölçümlerini kayıt altına almak', 'Komşu Lidya Krallığı\'na karşı resmi savaş ilanını kaya duvarlarına kazımak'], 'Yeni Frigce ve Eski Frigce mezar/anıt yazıtlarında anıta kötülük edene Kybele veya tanrıların lanetini dileyen koruyucu beddua kalıpları yaygın bir gelenektir.'),
  ('Gordion\'daki Yassıhöyük kazılarında MÖ 800 civarına tarihlenen büyük yangın tabakasının içinde mutfak kapları, dokuma tezgâhı ağırlıkları ve demir aletlerin olduğu gibi korunmuş çıkması arkeologlara ne sağlamıştır?', 'Frig saray ekonomisinin tekstil ve gıda üretimi organizasyonunu anlık bir kesit halinde inceleme olanağı', ['Büyük İskender\'in Gordion\'da kurduğu kütüphanedeki papirüsleri okuma fırsatı', 'Lidyalıların bastığı ilk altın sikkelerin darphane kalıplarını bulma şansı', 'Roma lejyonlarının kışla mutfağında tükettiği baharat türlerini saptama imkânı'], 'Gordion Erken Frig Tahrip Tabakası (MÖ ~800), yüzlerce tezgâh ağırlığı ve erzak kabıyla saraya bağlı dev tekstil ve aşevi atölyelerini adeta dondurulmuş şekilde günümüze ulaştırmıştır.'),
  ('İyonya\'nın on iki şehrinden biri olan Kolophon (Değirmendere) ile Efes arasında yer alan Klaros Kutsal Alanı\'nda kazılarla ortaya çıkarılan yer altı tonozlu koridorlar hangi tanrının kehanet törenlerine aittir?', 'Apollon', ['Ares', 'Hephaistos', 'Poseidon'], 'İzmir Menderes\'teki Klaros, Didyma ile birlikte Batı Anadolu\'nun en önemli iki Apollon bilicilik (kehanet) merkezinden biridir.'),
  ('Antik Anadolu uygarlıkları bir bütün olarak değerlendirildiğinde Hitit ve Urartuların merkezi krallık yapısına karşılık İyonya ve Likya\'da şehir devletleri veya federasyonların görülmesinde en belirleyici coğrafi faktör nedir?', 'Kıyı Ege ve Teke Yarımadası\'nda dağların denize dik veya sarp uzanarak korunaklı küçük koy ve vadiler oluşturması', ['Kıyı bölgelerinde tatlı su kaynaklarının bulunmaması nedeniyle kalabalık orduların beslenememesi', 'İç Anadolu ve Doğu Anadolu\'da maden yataklarının hiç bulunmaması yüzünden ticaretin gelişmemesi', 'Ege kıyılarındaki iklimin tarıma elverişsiz olması nedeniyle halkın sürekli yer değiştirmesi'], 'Batı ve Güneybatı Anadolu\'nun dağlarla bölünmüş parçalı kıyı topoğrafyası, geniş merkezi imparatorluklar yerine özerk polislerin ve Likya gibi şehir birliklerinin doğmasını kolaylaştırmıştır.'),
  ('Fethiye\'nin Tlos, Pinara ve Kadyanda gibi Likya kentlerinin akropollerinde yer alan yüksek kayalık kaleler ile kıyıdaki Andriake (Myra limanı) tahıl ambarları (horrea) birlikte düşünüldüğünde bölge ekonomisi nasıl tanımlanır?', 'Yayla tarımı ve sedir keresteciliğini uluslararası deniz ticaretiyle bütünleştiren çok yönlü ekonomi', ['Yalnızca korsanlıktan elde edilen ganimetlere dayanan üretimsiz kıyı ekonomisi', 'İç bölgelerle tüm yollarını kapatmış kendi kendine yeten kapalı köy ekonomisi', 'Sadece altın madenlerinin işletilmesine dayalı tek ürünlü saray ekonomisi'], 'Likya hem Torosların sedir ormanları ve yayla ürünlerini hem de Patara ve Andriake gibi gelişmiş liman ambarlarıyla Akdeniz deniz ticaretini birleştirmiştir.'),
  ('Frig kaya mimarisinde Aslantaş ve Yılantaş gibi anıtlarda mezar odası girişinin iki yanında şaha kalkmış devasa aslan kabartmalarının işlenmesi hangi inancın ifadesidir?', 'Kutsal alanı ve ölünün ebedi istirahatgâhını kötü güçlere karşı koruma (apotropaik) düşüncesi', ['Bölgede aslan avcılığının krallık yasalarıyla halka zorunlu kılındığını duyurma amacı', 'Mezar sahibinin sağlığında vahşi hayvan terbiyecisi olduğunu belirtme geleneği', 'Pers imparatorluk armasını Frig tapınaklarına resmen kabul ettirme zorunluluğu'], 'Afyonkarahisar Göynüş Vadisi\'ndeki Aslantaş ve Yılantaş mezarlarındaki görkemli aslanlar, Kybele\'nin kutsal hayvanı ve mezarın doğaüstü bekçileri olarak yontulmuştur.'),
  ('Tokat ve Niksar\'da Danişmendli hükümdarı Nizameddin Yağıbasan tarafından 12. yüzyıl ortalarında inşa ettirilen Yağıbasan Medresesi\'nin Anadolu eğitim tarihindeki ayrıcalıklı konumu nedir?', 'Anadolu\'da kurulan ilk medrese örneklerini oluşturması', ['Yalnızca yabancı elçilere dil öğreten tercüme okulu olması', 'Avrupa üniversitelerinden davet edilen hekimlerce yönetilmesi', 'Bütün derslerinin deniz haritacılığı ve gemi inşasına ayrılması'], 'Danişmendlilere ait Tokat ve Niksar Yağıbasan Medreseleri (1151-1158), kubbeli kapalı avlu planıyla Anadolu\'da bilinen en eski medrese yapılarıdır.'),
  ('Erzincan\'ın Tercan ilçesinde kendi adına kervansaray, hamam, mescit ve dilimli gövdeli özgün bir kümbetten oluşan külliye inşa ettiren kadın hükümdar hangi Türk beyliğinin başında bulunmuştur?', 'Saltuklu Beyliği (Melike Mama Hatun)', ['Mengücekli Beyliği (Melike Fahrünnisa Hatun)', 'Danişmendli Beyliği (Melike Gevher Nesibe)', 'Çaka Beyliği (Melike Devletşah Hatun)'], 'II. İzzeddin Saltuk\'un kızı Melike Mama Hatun 1191-1200 yılları arasında Saltuklu tahtına çıkmış ve İpek Yolu üzerindeki Tercan\'da ünlü külliyesini yaptırmıştır.'),
  ('Çaka Bey\'in Midilli, Sakız ve Sisam adalarını fethettikten sonra Bizans İmparatorluğu\'nu kesin olarak dize getirmek amacıyla Balkanlar\'daki hangi Türk topluluğuyla İstanbul kuşatması için ittifak kurduğu bilinmektedir?', 'Peçenekler', ['İdil boylarında ticaret devleti kuran Bulgarlar', 'Karadeniz\'in kuzeyinde Museviliği benimseyen Hazarlar', 'Orta Asya\'da Karahanlı mirasını sürdüren Karluklar'], 'Çaka Bey denizden, Trakya\'ya inen Peçenek Türkleri ise karadan İstanbul\'u kuşatmak üzere anlaşmış; ancak Bizans İmparatoru I. Aleksios Kumanları Peçenekler üzerine kışkırtarak bu planı bozmuştur.'),
  ('Güneydoğu Anadolu\'da kurulan Artuklu Beyliği\'nin yönetim tarihinde tek bir merkez yerine üç ayrı koldan hüküm sürdüğü şehirler aşağıdakilerin hangisinde doğru eşleştirilmiştir?', 'Hasankeyf, Mardin ve Harput', ['Erzurum, Kars ve Bayburt', 'Sivas, Tokat ve Amasya', 'Kemah, Divriği ve Şebinkarahisar'], 'Artuk Bey\'in oğulları ve torunları Güneydoğu Anadolu\'da Hasankeyf (Hısnıkeyfa), Mardin (İlgaziler) ve Harput olmak üzere üç siyasi kolda varlık göstermiştir.'),
  ('Anadolu\'nun fethi sürecindeki gazilik ruhunu, kerametleri ve Bizans tekfurlarıyla yapılan mücadeleleri destansı bir dille anlatan, II. İzzeddin Keykavus devrinde yazıya geçirilen eser hangisidir?', 'Danişmendname', ['Kutadgu Bilig', 'Atabetü\'l-Hakayık', 'Mecalisü\'n-Nefais'], 'Melik Danişmend Ahmet Gazi ve silah arkadaşlarının Anadolu\'yu vatan yapma mücadelelerini destanlaştıran \'Danişmendname\', Türk halk edebiyatı ve tarih bilincinin temel metinlerindendir.'),
  ('19 Mayıs 1090 tarihinde Çaka Bey komutasındaki Türk filosu ile Bizans Amirali Niketas Kastamonites donanması arasında Sakız Adası yakınlarında gerçekleşen ve ilk Türk deniz zaferi sayılan muharebe hangisidir?', 'Koyun Adaları Deniz Savaşı', ['Preveze Açık Deniz Muharebesi', 'Zatü\'s-Savari Yelken Savaşı', 'Çeşme Limanı Baskını'], 'Çaka Bey\'in Sakız ile Karaburun arasındaki Koyun Adaları (Oinousses) mevkiinde Bizans donanmasını bozguna uğratması Türk tarihinin ilk büyük deniz zaferidir.'),
  ('Bitlis\'in Ahlat ilçesinde Sökmenliler (Ahlatşahlar) döneminden itibaren şekillenen, boyları dört metreyi bulan mukarnaslı ve geometrik oymalı binlerce mezar taşı (şahide) hangi tarihsel niteliğiyle öne çıkar?', 'Orta Asya balbal geleneğini İslami taş işçiliğiyle birleştiren Türk tapu senedi niteliğindeki açık hava müzesi olmasıyla', ['Bizans imparatorlarının yazlık saray bahçesindeki mermer sütunların yeniden dikilmesiyle oluşmasıyla', 'Haçlı şövalyelerinin Kudüs yolunda bıraktığı Latince kitabeli anıtlardan meydana gelmesiyle', 'Yalnızca deniz savaşlarında şehit düşen kaptanların defnedildiği kıyı şehitliği olmasıyla'], '\'Kubbetü\'l-İslam\' unvanlı Ahlat\'taki Selçuklu/Ahlatşahlar Meydan Mezarlığı, anıtsal taş şahideleriyle Türklerin Anadolu\'daki köklü varlığının simgesidir.'),
  ('Bizans İmparatoru I. Aleksios Komnenos\'un, damadı Türkiye Selçuklu Sultanı I. Kılıçarslan\'a mektup yazarak kayınpederi Çaka Bey\'in \'Selçuklu tahtında gözü olduğu\' kışkırtmasında bulunması nasıl sonuçlanmıştır?', 'I. Kılıçarslan\'ın Bizans entrikasına kapılarak Çaka Bey\'i ortadan kaldırması ve Türk deniz hamlesinin duraklamasıyla', ['İki Türk hükümdarının birleşerek Bizans donanmasını Marmara\'da tamamen yakmasıyla', 'Çaka Bey\'in İzmir\'i gönüllü olarak Selçuklulara devredip Mısır\'a yerleşmesiyle', 'Peçenek ordusunun Anadolu\'ya geçerek İznik\'i kuşatmasıyla'], 'Bizans\'ın geleneksel \'böl ve birbirine düşür\' diplomasisi sonucu I. Kılıçarslan, kayınpederi Çaka Bey\'i 1093 civarında öldürtmüş ve Ege\'deki erken Türk denizciliği ağır darbe almıştır.'),
  ('El-Cezerî\'nin \'Kitabü\'l-Hiyel\' adlı eserinde çizimlerini verdiği \'Filli Su Saati\'nde Hint fili, Çin ejderi, Mısır zümrüdüanka kuşu ve Arap kıyafetli figürlerin bir arada kullanılması neyi simgeler?', 'Bilim ve teknolojinin farklı medeniyetlerin ortak mirası olduğu yönündeki evrensel bakışı', ['Artuklu ordusunun Hindistan\'dan Mısır\'a kadar tüm kıtaları fethettiği iddiasını', 'Saatin parçalarının dört ayrı ülkeden ithal edilmeden çalışamayacağı zorunluluğunu', 'Yalnızca yabancı tüccarların anlayabileceği gizli bir ticari şifre oluşturma isteğini'], 'El-Cezerî Filli Su Saati\'nde farklı kültürlerin sembollerini bilinçli biçimde birleştirerek İslam bilim dünyasının sentezci ve evrensel karakterini yansıtmıştır.'),
  ('Divriği Ulu Camii ve Darüşşifası\'nın vakfiyesinde ve kitabelerinde, cami bölümünü Mengücekli Ahmet Şah\'ın, bitişiğindeki şifahane bölümünü ise eşi Melike Turan Melek\'in kendi şahsi servetiyle yaptırdığının belirtilmesi neyi kanıtlar?', 'Hanedan kadınlarının ekonomik özerkliğe sahip olarak kamusal sağlık ve hayır kurumları kurabildiğini', ['Hükümdarların dini binalar dışında hastane yaptırmasının yasalarla engellendiğini', 'Kadınların yaptırdığı yapılara erkek hastaların kabul edilmesinin yasak olduğunu', 'Devlet hazinesinin iflas etmesi nedeniyle vergilerin kadınlar tarafından toplandığını'], 'Türk-İslam beyliklerinde hatunlar şahsi mülklerini vakıflara dönüştürerek darüşşifa, kervansaray ve kümbet gibi büyük sosyal kurumların banisi olmuşlardır.'),
  ('Türkiye Selçuklu Sultanı II. Kılıçarslan\'ın 1175-1178 yıllarında Danişmendli Beyliği\'nin Sivas, Tokat ve Malatya kollarına son vererek topraklarını ilhak etmesi hangi stratejik hedefe yöneliktir?', 'Miryokefalon Savaşı sürecinde Anadolu Türk siyasi birliğini tek merkezde toplamak', ['Doğu Anadolu\'daki tüm ticaret yollarını Gürcü Krallığı\'na devretmek', 'Haçlı ordularının Kudüs\'e engelsiz geçiş yapabileceği bir koridor açmak', 'Başkenti Konya\'dan çıkarıp İzmir limanına taşımak'], 'Anadolu\'da Türkiye Selçuklularının en güçlü Türk rakibi olan Danişmendlilerin II. Kılıçarslan tarafından ortadan kaldırılması, Anadolu Türk birliği yolunda en kritik adım olmuştur.'),
  ('Mardin\'de Artuklular devrinde inşa edilen Eminüddin Külliyesi, Ulu Cami, Şehidiye ve Zinciriye (Sultan İsa) medreselerinin ortak kentsel ve mimari özelliği aşağıdakilerden hangisidir?', 'Sarı kalker taşından dilimli kubbelerle Güneydoğu Mezopotamya ovasına bakan teraslı yamaca dizilmeleri', ['Tamamen sırlı mavi çinilerle kaplanarak düz bir nehir yatağına inşa edilmeleri', 'Karadeniz yayla mimarisine uygun biçimde kestane ağacından çantı tekniğiyle kurulmaları', 'Etrafında hendekler bulunan tek katlı kerpiç kaleler içine gizlenmeleri'], 'Mardin Artuklu mimarisi, yöreye özgü kolay işlenen sarı kalker taşı, dilimli kubbeleri ve ovaya hâkim kademeli teras yerleşimiyle benzersiz bir silüet oluşturmuştur.'),
  ('Kayseri Ulu Camii (Cami-i Kebir) 12. yüzyılda hangi Türk beyliğinin hükümdarı Melik Mehmed Gazi tarafından inşa ettirilerek İç Anadolu\'nun en önemli dini yapılarından biri haline getirilmiştir?', 'Danişmendliler', ['Saltuklular', 'Çaka Beyliği', 'Dilmaçoğulları'], 'Kayseri\'yi önemli bir merkez yapan Danişmendli hükümdarı Melik Mehmed Gazi (1134-1142), Kayseri Ulu Camii\'ni inşa ettirerek kentin İslami kimliğini güçlendirmiştir.'),
  ('Büyük Selçuklu komutanı Artuk Bey\'in Kudüs valiliği de yaptıktan sonra oğulları Sökmen ve İlgazi\'nin Güneydoğu Anadolu\'ya yerleşmesi, bölgenin siyasi kaderini nasıl etkilemiştir?', 'Diyarbakır, Mardin ve Urfa hattının Haçlı yayılmasına karşı güçlü bir Türk-İslam kalkanı olmasını sağlamıştır', ['Bölgenin hiçbir savunma yapılmadan Fatımi Halifeliğine teslim edilmesine yol açmıştır', 'Güneydoğu Anadolu\'daki İpek ve Baharat yolu bağlantılarının tamamen kapanmasına neden olmuştur', 'Bütün Türkmen boylarının Mezopotamya\'yı terk ederek Karadeniz dağlarına çekilmesini getirmiştir'], 'Artuklular Urfa Haçlı Kontluğu ve Antakya Prensliği ile göğüs göğüse çarpışarak Güneydoğu Anadolu\'nun Haçlıların eline geçmesini önlemişlerdir.'),
  ('Türkiye Selçuklu Sultanı I. Alaeddin Keykubad\'ın 1228\'de Mengüceklilerin Erzincan-Kemah koluna, 1230\'da ise Erzurum\'daki Saltuklu bakiyesi/Selçuklu melikliğine son vererek Doğu Anadolu\'yu doğrudan merkeze bağlamasının temel gerekçesi nedir?', 'Doğudan yaklaşan Harzemşah ve Moğol tehlikesine karşı stratejik sınır kalelerini tek elden tahkim etmek', ['Venedik donanmasının Karadeniz\'den Fırat Nehri\'ne girmesini engellemek', 'Doğu Anadolu\'daki tüm medreseleri kapatıp âlimleri Konya\'da toplamak', 'Bizans İmparatorluğu ile birlikte Gürcistan\'ı ikiye bölüp paylaşmak'], 'İleri görüşlü bir devlet adamı olan I. Alaeddin Keykubad, doğudaki Moğol istilası dalgasını görerek Erzincan, Kemah ve Erzurum gibi kilit kaleleri doğrudan Selçuklu savunma hattına katmıştır.'),
  ('Çaka Bey\'in Bizans sarayında esir olarak bulunduğu gençlik yıllarında \'Protonobilissimos\' gibi yüksek bir Bizans asalet unvanı alması ve Grekçeyi çok iyi öğrenmesi İzmir\'deki faaliyetlerine nasıl yansımıştır?', 'Yerli Rum gemi ustalarını istihdam ederek Bizans deniz taktiklerine uygun modern bir donanma kurabilmiştir', ['Türkmen savaşçılarını ordusundan uzaklaştırarak yalnızca Venedikli paralı askerler kullanmıştır', 'İzmir Beyliği\'nin resmi yazışma dilini Latince olarak ilan etmiştir', 'Ege adalarındaki tüm kaleleri Bizans İmparatoru adına vergiye bağlamıştır'], 'Çaka Bey Bizans sarayında edindiği diplomasi ve denizcilik bilgisini Türk akıncı ruhuyla birleştirmiş; İzmir ve Efes\'teki tersane olanaklarını kullanarak güçlü bir filo oluşturmuştur.'),
  ('Hasankeyf\'te Dicle Nehri üzerinde Artuklu hükümdarı Fahreddin Kara Arslan tarafından 12. yüzyıl ortasında inşa ettirilen ve orta ayaklarında burç kabartmaları taşıyan görkemli yapı hangisidir?', 'Hasankeyf Eski Köprüsü', ['Tercan Kervansaray Kemeri', 'Niksar Talazan Köprüsü', 'Sivas Eğri Köprü'], 'Orta Çağ seyyahlarının hayranlıkla anlattığı Hasankeyf Artuklu Köprüsü, orta açıklığı zamanında açılıp kapanabilen ahşap tertibatlı dev taş ayaklarıyla ünlüdür.'),
  ('Mengüceklilerin Divriği kolunun yaklaşık bir buçuk yüzyıl boyunca askeri fetihlerden çok mimari, tıp, astronomi ve zanaat eserleriyle anılmasında hangi jeopolitik koşul etkili olmuştur?', 'Türkiye Selçuklu Devleti\'nin yüksek himayesini kabul ederek barış ve istikrar ortamını korumaları', ['Deniz aşırı sömürgelerden gelen baharat vergileriyle büyük servet biriktirmeleri', 'Etrafının geçit vermez çöllerle çevrili olması yüzünden hiçbir ordunun bölgeye ulaşamaması', 'Moğol hükümdarı Cengiz Han ile akrabalık kurarak vergiden muaf tutulmaları'], 'Divriği Mengüceklileri Türkiye Selçuklu sultanlarına bağlı kalarak yıkıcı savaşlardan uzak durmuş ve gelirlerini Divriği Külliyesi, Kale Camii ve Sitte Melik Kümbeti gibi şaheserlere yöneltmiştir.'),
  ('Diyarbakır Ulu Camii avlusunda bugün de yer alan ve güneşin gölgesiyle namaz ile mevsim vakitlerini hassas biçimde gösteren mermer güneş saati hangi dönemin bilimsel mirasıdır?', 'Artuklu dönemi astronomi ve mühendislik çalışmalarının', ['Roma İmparatoru Konstantin dönemi lejyon mühendisliğinin', 'Osmanlı Tanzimat devrinde kurulan Muvakkithane idaresinin', 'Urartu krallarının Güneş Tanrısı Şivini için diktiği sunakların'], 'Diyarbakır Ulu Camii avlusundaki mermer sütunlu güneş saati, Artuklu devrinde El-Cezerî ve çağdaşı âlimlerin astronomi-mekanik bilgisini yansıtan nadide bir eserdir.'),
  ('1101 yılı yazında Anadolu\'yu geçmeye çalışan üç büyük Haçlı ordusunun Merzifon ve Ereğli\'de imha edilmesinde Türkiye Selçuklu Sultanı I. Kılıçarslan ile omuz omuza çarpışan Türk beyliği hangisidir?', 'Danişmendliler', ['Karesioğulları', 'Menteşeoğulları', 'Çaka Beyliği'], 'Bohemund\'u kurtarmak ve Kudüs\'e gitmek isteyen 1101 yılı Haçlı ordularına karşı I. Kılıçarslan ile Danişmend Gazi ve Harran Emiri Karaca güç birliği yaparak büyük zaferler kazanmıştır.'),
  ('Artuklu sikkeleri ve taş kabartmaları üzerinde (örneğin Diyarbakır surlarının Yedi Kardeş ve Evli Beden burçlarında) çift başlı kartal ve kanatlı aslan (sfenks) figürlerinin yer alması neyi ifade eder?', 'Orta Asya Türk kozmolojisi ile Mezopotamya-Anadolu hükümdarlık sembollerinin kaynaştığını', ['İslam dünyasında yazı kullanımının taş yüzeylerde yasaklandığını', 'Burçların Haçlı şövalyeleri tarafından armalarıyla süslendiğini', 'Bu yapıların İslamiyet öncesi Sâsânî ateşgedeleri olduğunu'], 'Artuklu Hükümdarı Melik Salih Mahmud döneminde Usta İbrahim bin Cafer\'in yaptığı Diyarbakır burçlarındaki çift başlı kartal ve kanatlı aslanlar, Türk hâkimiyet ve koruyucu güç simgeleridir.'),
  ('Saltuklu hükümdarı İzzeddin Saltuk zamanında Erzurum ve Tercan üzerinden geçen kervan yolunun güvenliğinin sağlanması hangi iki büyük ekonomik havza arasındaki ticareti canlandırmıştır?', 'İran-Tebriz İpek Yolu hattı ile Karadeniz\'deki Trabzon limanı arasındaki transit ticareti', ['Mısır Nil deltası ile Cebelitarık Boğazı arasındaki baharat deniz ticaretini', 'Baltık Denizi kehribar ocakları ile Orta Avrupa panayırları arasındaki ticareti', 'Hindistan limanları ile Basra Körfezi arasındaki inci avcılığı ticaretini'], 'Tebriz-Doğubayazıt-Erzurum-Tercan-Bayburt-Trabzon güzergâhı Orta Çağ\'ın en işlek İpek Yolu kollarından biri olup Saltuklu ve Mengücekli refahının ana kaynağıdır.'),
  ('Divriği Ulu Camii\'nin batı taç kapısında ikindi güneşi vurduğunda taş kabartmaların oluşturduğu gölgenin kıyama durmuş ve kitap okuyan bir insan silüeti meydana getirmesi neyin kanıtıdır?', 'Taş yontu sanatının astronomik ışık-gölge açıları hesaplanarak üç boyutlu tasarlandığının', ['Deprem kaymaları sonucunda taş blokların tesadüfen yer değiştirdiğinin', 'Cumhuriyet döneminde kapı yüzeyine lazerle yeni oyuklar açıldığının', 'Bizans döneminden kalma bir aziz heykelinin sıva altından çıktığının'], 'Mimar Hürremşah ve taş ustaları, güneşin geliş açısını hesaplayarak yüksek kabartmalı mukarnas ve yaprak motifleriyle belirli saatlerde insan gölgesi düşüren eşsiz bir optik sanat üretmiştir.'),
  ('Niksar ve Tokat\'ta yükselen Danişmendli medreselerinde kubbenin ortasında bırakılan geniş aydınlık feneri (açıklık) ve altındaki havuz mimari açıdan hangi ihtiyacı karşılamıştır?', 'Sert karasal iklimde kapalı avlulu yapının hem doğal ışık almasını hem de iç mekân ferahlığını sağlamayı', ['Yağmur sularıyla medrese odalarını su altında bırakarak yangını önlemeyi', 'Okçuluk talimi yapan öğrencilerin gökyüzündeki kuşları hedef almasını', 'Kış aylarında binanın çatısında biriken karların doğrudan sınıflara dökülmesini'], 'Orta ve Kuzey Anadolu\'nun soğuk kış koşullarına uyum sağlayan kapalı avlulu medrese tipinde, orta kubbedeki aydınlık feneri ısıyı korurken ışık ve havalandırma sağlamıştır.'),
  ('Çaka Bey\'in sadece İzmir\'le yetinmeyip Çanakkale Boğazı girişindeki Abydos (Nara) Kalesi\'ni kuşatması hangi büyük stratejik hedefi güttüğünü ortaya koyar?', 'Ege\'den Marmara Denizi\'ne geçerek Bizans başkentinin deniz ikmal yolunu boğazdan kesmek', ['Karadeniz üzerinden Kırım yarımadasındaki buğday limanlarına yerleşmek', 'Akdeniz\'i aşarak Mısır\'daki İskenderiye tersanesini ele geçirmek', 'Adriyatik Denizi\'ne girerek Venedik Cumhuriyeti\'ni vergiye bağlamak'], 'Midilli ve Sakız\'dan sonra Çanakkale Boğazı kilit noktası Abydos\'u kuşatan Çaka Bey, Marmara\'ya girip İstanbul\'u denizden ablukaya almayı planlamıştır.'),
  ('El-Cezerî\'nin tasarladığı \'Abdest Alma ve El Yıkama Otomatı\'nda hükümdar yıkandıktan sonra mekanik bir çocuk/hizmetkâr figürünün elindeki havlu ve tarağı uzatması hangi ilkeyle çalışmaktadır?', 'Boşalan su haznesindeki şamandıra ve ağırlık kollarının sırayla tetiklediği hidro-mekanik dengeyle', ['Sarayın bodrumundaki kölelerin duvar arkasından gizlice ipleri çekmesiyle', 'Güneş aynalarının ısıttığı cıvanın cam borularda genleşmesiyle', 'Barut kapsüllerinin küçük patlamalarla dişli çarkları döndürmesiyle'], 'El-Cezerî hiçbir insan hilesi kullanmadan; su basıncı, sifon (kaide-i butlan), şamandıra ve karşı ağırlık sistemleriyle programlanabilir mekanik otomatlar üretmiştir.'),
  ('Ahlat\'ın Orta Çağ İslam dünyasında Belh ve Buhara ile birlikte \'Kubbetü\'l-İslam\' (İslam\'ın Kubbesi) unvanıyla anılan üç şehirden biri olmasını sağlayan temel özelliği nedir?', 'Çok sayıda âlim, mutasavvıf, mimar ve sanatkâr yetiştiren büyük bir kültür ve ilim merkezi olması', ['Dünyanın en yüksek kubbeli saray binasının bu şehirde inşa edilmiş olması', 'Halifelik makamının Bağdat\'tan sonra yüz yıl boyunca Ahlat\'ta bulunması', 'Bütün İslam ordularının silah ve barut ihtiyacını tek başına üretmesi'], 'Sökmenliler (Ahlatşahlar) devrinde zirveye çıkan Ahlat; yetiştirdiği müderrisler, mutasavvıflar ve Divriği ile Konya\'da eser veren taş ustaları sayesinde \'Kubbetü\'l-İslam\' unvanını almıştır.'),
  ('Mengüceklilerin Erzincan sarayında gelişen ilim ve kültür ortamının 1243 Kösedağ Savaşı sonrasındaki Moğol istilasına kadar kesintisiz sürmesi Doğu Anadolu\'ya hangi mirası bırakmıştır?', 'Türk-İslam kimliğinin Yukarı Fırat havzasında sarsılmaz biçimde kök salmasını', ['Bölge halkının konuşma dili olarak yalnızca Moğolcayı benimsemesini', 'Erzincan ve Kemah çevresinin tamamen insansız bozkıra dönüşmesini', 'Trabzon Rum İmparatorluğu\'nun Fırat kıyılarına kadar genişlemesini'], 'Mengüceklilerin 150 yılı aşkın imar, vakıf ve iskân faaliyetleri sayesinde Erzincan, Kemah ve Divriği havzası kalıcı bir Türk-İslam kültür yurdu haline gelmiştir.'),
  ('El-Cezerî\'nin şifreli kilitli sandıklar, kan alma ölçüm kapları ve su saatleri tasarlarken tüm çizimlerini ölçüleriyle ve yapım aşamalarıyla adım adım yazmasının bilim tarihindeki değeri nedir?', 'Deneysel tekrarlanabilirliğe imkân veren uygulamalı bir mühendislik kılavuzu oluşturması', ['Buluşlarını kimsenin anlamaması için sembolik büyü harfleriyle gizlemesi', 'Yalnızca teorik felsefe tartışmaları yapıp pratik üretimden uzak durması', 'Antik Yunan metinlerini hiçbir ekleme yapmadan Arapçaya tercüme etmesi'], 'El-Cezerî kendisinden önceki bazı teorik yazarların aksine bizzat imal edip çalıştırdığı makineleri modern teknik resim mantığına yakın biçimde açıkça tarif etmiştir; bugün bu çizimlerle makineleri birebir çalıştırılabilmektedir.'),
  ('Erzurum\'daki \'Üç Kümbetler\' topluluğunun en büyüğü ve taş işçiliği bakımından en görkemlisi olan sekizgen gövdeli anıt mezar hangi Saltuklu hükümdarına atfedilmektedir?', 'Emir Saltuk', ['Çaka Bey', 'Artuk Bey', 'Süleymanşah'], 'Erzurum Üç Kümbetler içindeki en anıtsal yapı olan Emir Saltuk Kümbeti (12. yüzyıl), çift renkli kesme taş işçiliği ve nişlerdeki boğa-yılan-kartal kabartmalarıyla ünlüdür.'),
  ('Tokat Niksar Kalesi\'nin ve buradaki Yağıbasan Medresesi ile Melik Gazi Türbesi\'nin Danişmendli tarihindeki özel yeri aşağıdakilerden hangisiyle açıklanır?', 'Beyliğin ilk kuruluş başkenti ve askeri-kültürel kalbi olmasıyla', ['Karadeniz donanmasının kışlak tersanesi olarak hizmet vermesiyle', 'Türkiye Selçukluları ile Moğollar arasında sınır antlaşmasının burada imzalanmasıyla', 'Yalnızca gayrimüslim tüccarların yaşadığı serbest gümrük bölgesi olmasıyla'], 'Karadeniz geçitlerine hâkim müstahkem Niksar kenti, Danişmend Gazi\'den itibaren beyliğin ilk başkenti, darphane ve eğitim merkezi olmuştur.'),
  ('Anadolu\'daki birinci dönem Türk beylikleri ile Büyük Selçuklu İmparatorluğu arasındaki hukuki-siyasi bağ en doğru biçimde nasıl tanımlanabilir?', 'İç işlerinde geniş özerkliğe sahip olmakla birlikte hutbe ve sikkede Büyük Selçuklu sultanını üst metbu tanıyan tabi beylikler', ['Büyük Selçuklu Devleti ile hiçbir diplomatik veya hanedan bağı bulunmayan tamamen yabancı krallıklar', 'Merkez İsfahan\'dan her yıl maaşla atanan ve iki yılda bir görev yeri değiştirilen memur valilikler', 'Bizans İmparatorluğu\'na bağlı olup Büyük Selçuklu ordularına karşı sınır bekçiliği yapan uç kaleleri'], 'İlk Türk beyliklerini kuran komutanlar Sultan Alparslan ve Melikşah\'ın emirleri olduğundan, kurdukları beylikler Büyük Selçuklu İmparatorluğu\'nun yüksek hâkimiyetini tanımışlardır.'),
  ('Diyarbakır\'daki Mesudiye Medresesi\'nin (1198) mihrabının iki yanına yerleştirilen ve dönebilen taş sütunların (\'denge sütunları\') mimari mühendislikteki işlevi nedir?', 'Binanın temelinde deprem veya zemin oturması yaşandığında sıkışarak yapısal kaymayı önceden haber vermek', ['Öğrencilerin ders aralarında kol kaslarını güçlendirmesi için spor aleti olmak', 'Rüzgâr estiğinde dönerek medrese odalarına buğday unu öğütmek', 'Üzerindeki harflerle gizli devlet şifrelerini çözmeye yarayan çark olmak'], 'Artuklu ve Selçuklu medreselerinde mihrap yanlarına konulan döner \'terazi/denge sütunları\', yapı zemininde en ufak bir kayma olduğunda dönmeyi keserek erken uyarı görevi üstlenmiştir.'),
  ('Sultan I. Kılıçarslan\'ın 1107 yılında Musul\'u ele geçirdikten sonra Büyük Selçuklu emirleriyle yaptığı çarpışmada hangi nehrin sularında boğularak hayatını kaybetmesi devlette fetret devri başlatmıştır?', 'Habur Irmağı', ['Kuzey Suriye ovalarını sulayarak Akdeniz\'e dökülen Asi Nehri', 'Doğu Anadolu yaylalarından doğup Basra\'ya uzanan Dicle Nehri', 'Orta Anadolu bozkırlarını katederek Karadeniz\'e ulaşan Kızılırmak'], 'Musul seferi dönüşünde Emir Çavlı kuvvetleriyle Habur Irmağı kıyısında savaşan I. Kılıçarslan, atıyla ırmağı geçmeye çalışırken zırhının ağırlığıyla boğulmuş ve oğulları esir düşmüştür.'),
  ('12. yüzyılın ilk yarısında hem II. Haçlı Seferi ordularını Anadolu\'da yıpratan hem de Batılı kaynakların Anadolu için ilk kez \'Turchia\' (Türkiye) adını kullanmaya başladığı dönemde hüküm süren Selçuklu sultanı kimdir?', 'I. Mesud', ['Devleti yeniden Akdeniz kıyılarına açan I. Gıyaseddin Keyhüsrev', 'Danişmendli Beyliği\'nin tüm kollarına son veren II. Kılıçarslan', 'Harzemşah ordusunu Yassıçemen\'de mağlup eden I. Alaeddin Keykubad'], 'Sultan I. Mesud (1116-1155) kırk yıla yaklaşan saltanatında Alman İmparatoru III. Konrad ve Fransa Kralı VII. Louis\'nin Haçlı ordularını bozguna uğratmış, ilk bakır Selçuklu parasını kestirmiş ve imar hamlesi başlatmıştır.'),
  ('Sultan I. İzzeddin Keykavus\'un 1214 yılında Karadeniz kıyısındaki Sinop\'u Trabzon Rum İmparatorluğu\'ndan almasının hemen ardından şehirde başlattığı en stratejik askeri girişim nedir?', 'Kale tahkimatıyla birlikte Karadeniz\'e açılan bir tersane inşa ettirmesi', ['Şehirdeki tüm Rum tüccarları İç Anadolu bozkırlarına zorunlu göçe tabi tutması', 'Karadeniz üzerinden gelecek kervanlara yüksek oranlı gümrük yasağı koyması', 'Trabzon Rum hanedanıyla birleşerek ortak bir Ortodoks-İslam meclisi kurması'], 'Sinop\'un fethiyle Türkiye Selçukluları ithalat-ihracat kapısı olarak Karadeniz\'e çıkmış ve Sinop Tersanesi\'ni kurarak kuzey yönlü deniz gücü oluşturmuştur.'),
  ('I. Alaeddin Keykubad döneminde Kastamonu uç beyi Hüsameddin Çoban komutasında Sinop\'tan kalkan Selçuklu donanmasının Karadeniz\'i aşarak Kırım kıyısında ele geçirdiği ticaret limanı hangisidir?', 'Suğdak', ['Tuna Nehri ağzında tahıl sevkiyatını kontrol eden Kili', 'Azak Denizi girişinde Cenevizlilerin üs kurduğu Tana', 'Kafkasya sahilinde tuz ve köle pazarıyla bilinen Sohum'], 'Kıpçak bozkırları ve Rus kürk-köle ticaretinin Karadeniz\'deki kilit limanı Suğdak\'a düzenlenen denizaşırı sefer, Türkiye Selçuklu deniz gücünün zirvesini temsil eder.'),
  ('Yaklaşan Moğol istilası tehlikesini öngören I. Alaeddin Keykubad\'ın Konya, Kayseri ve Sivas surlarını kendi hazinesi ile emirlerin katkısıyla yeniden inşa ettirirken Eyyubiler ve Harzemşahlarla ittifak araması nasıl değerlendirilir?', 'İç savunma hazırlığını bölgesel diplomasiyle bütünleştiren ileri görüşlü güvenlik siyaseti', ['Anadolu\'daki tüm tarımsal yatırımları durdurup göçebe yaşam düzenine geri dönme çabası', 'Batı sınırındaki Bizans kalelerini savunmasız bırakarak ordusunu terhis etme girişimi', 'Abbasi Halifesi\'nin askeri yetkilerini elinden alıp Bağdat\'ı ilhak etme hazırlığı'], 'Alaeddin Keykubad bir yandan büyük şehirlerin surlarını tahkim ettirip doğudaki kaleleri onarmış, diğer yandan Moğollara karşı tampon devletlerle barışçı ittifak kurmaya çalışmıştır.'),
  ('I. Alaeddin Keykubad\'ın ölümünün ardından tahta çıkan II. Gıyaseddin Keyhüsrev devrinde devlet kademelerindeki tecrübeli komutan ve devlet adamlarını tasfiye ederek merkezi yönetimi zayıflatan saray görevlisi kimdir?', 'Sadeddin Köpek', ['Selçuklu darüşşifalarının vakıflarını denetleyen Celaleddin Karatay', 'Moğol tahakkümü yıllarında yönetimi elinde tutan Muineddin Pervane', 'Kastamonu uç bölgesinde Kırım seferini yöneten Hüsameddin Çoban'], 'Emir-i Şikâr ve mimar kökenli Sadeddin Köpek, genç sultan II. Gıyaseddin Keyhüsrev\'i etkileyerek Harzemli komutanları ve değerli devlet adamlarını öldürtmüş, devletin direncini kırmıştır.'),
  ('Türkiye Selçuklu hükümdarlarının Büyük Selçuklu sultanlarından farklı olarak Farsça kökenli \'Keyhüsrev, Keykavus ve Keykubad\' gibi unvanlar kullanmaları hangi tarihsel olguyla açıklanır?', 'İran edebiyat ve hükümdarlık kültürünün saray protokolündeki derin etkisiyle', ['Selçuklu hanedanının baba tarafından Sasani krallarının soyundan gelmesiyle', 'Abbasi halifelerinin Türkçe unvan kullanılmasını fermanla yasaklamasıyla', 'Anadolu\'daki yerli Rum ahalinin Farsça dışındaki dilleri bilmemesiyle'], 'Firdevsî\'nin Şehnâme\'sindeki efsanevi İran hükümdar adları (Keyhüsrev, Keykavus, Keykubad), yüksek İran saray kültürünün Türkiye Selçuklu hanedanı üzerindeki güçlü tesirini gösterir.'),
  ('Büyük Selçuklu teşkilatında bulunmayan ancak Türkiye Selçuklu Devleti\'nde hükümdar başkentte olmadığında veya tahtta küçük yaşta bir sultan bulunduğunda sultan adına devleti yöneten üst düzey makam hangisidir?', 'Nâib-i Saltanat', ['Saray mutfağını ve sofra güvenliğini yöneten Çaşnigir', 'Savaş ganimetlerinin beşte birini hesaplayan Kassam', 'Yabancı tüccarların gümrük defterlerini tutan Bacdar'], 'Niyabet-i Saltanat makamı Türkiye Selçuklularına özgü önemli bir yeniliktir; hükümdarın seferde olduğu sıralarda Nâib-i Saltanat merkezde sultan vekili olarak görev yapardı.'),
  ('Türkiye Selçuklu Divan-ı Saltanat üyelerinden \'Pervaneci\' unvanlı görevlinin devlet idaresindeki asli sorumluluk alanı aşağıdakilerden hangisidir?', 'Arazi defterlerini tutarak ikta ve mülk topraklarının atama menşurlarını hazırlamak', ['Sultanın özel av partilerini ve yırtıcı av kuşlarının bakımını organize etmek', 'Şehir pazarlarındaki ölçü ve tartı aletlerinin doğruluğunu her hafta denetlemek', 'Donanma tersanelerindeki gemi inşası için gerekli kereste sevkiyatını yürütmek'], 'Türkiye Selçuklularında Büyük Divan\'da mülk ve ikta tevcihatını yürüten, bunlara ait \'pervane\' adlı fermanları düzenleyen divan üyesine Pervaneci denilirdi; zamanla vezir kadar güçlenmiştir.'),
  ('Selçuklu merkezi yönetiminde devletin bütün gelir ve gider hesaplarını tutan, vergilerin toplanmasını ve hazine dengesini denetleyen maliye bakanı konumundaki divan üyesi kimdir?', 'Müstevfî', ['Örfi mahkemelerde asayiş suçlarını yargılayan Emir-i Dâd', 'Ordunun yoklama ve maaş kayıtlarını tutan Emir-i Arz', 'Saray muhafız kıtalarının nöbet düzenini sağlayan Candar'], 'Divan-ı İstifa\'nın başkanı olan Müstevfî, devlet bütçesini hazırlayan, vilayetlerin vergi tahsilatını ve harcamalarını denetleyen en üst maliye yetkilisidir.'),
  ('Divan-ı Saltanat\'ta iç ve dış resmi yazışmaları kaleme alan, fermanlara sultanın tuğrasını çeken \'Divan-ı Tuğra (İnşa)\' başkanı aşağıdakilerden hangisidir?', 'Tuğrâî', ['Şehirlerin belediye ve pazar düzeninden sorumlu olan Muhtesip', 'Vilayetlerde askeri güvenliği sağlayan garnizon komutanı Subaşı', 'Saray ile eyaletler arasındaki gizli haberleşmeyi yürüten Berid'], 'Yüksek edebiyat ve diplomasi bilgisine sahip olan Tuğrâî (Sahib-i Divan-ı Tuğra / Münşî), dış devletlere gönderilen nameleri ve sultan fermanlarını hazırlardı.'),
  ('Türkiye Selçuklu ordusunun asker mevcudunu, silah-teçhizat durumunu ve ikta-maaş (bistegânî) defterlerini tutan \'Divan-ı Arz\'ın başındaki görevli hangisidir?', 'Emir-i Arz', ['Sarayın iç hizmetlilerini eğiten ve denetleyen Üstadü\'d-Dâr', 'Hükümdarın silahlarını taşıyan ve silahhaneyi koruyan Silahdâr', 'Kervansarayların yıllık onarım keşiflerini yapan Mimarbaşı'], 'Ordunun idari ve lojistik ihtiyaçlarını karşılayan, geçit törenlerinde yoklama yapan Divan-ı Arz\'ın başkanına Emir-i Arz veya Ârızü\'l-Ceyş denilirdi.'),
  ('Selçuklu sarayının ve bizzat hükümdarın can güvenliğini sağlamakla yükümlü muhafız birliğinin komutanına verilen unvan aşağıdakilerden hangisidir?', 'Emir-i Candar', ['Sancak ve bayrakların muhafazasından sorumlu Emir-i Alem', 'Resmi kabullerde elçileri sultana takdim eden Hâcibü\'l-Hüccâb', 'Hükümdarın elbiselerinin dikim ve korunmasına bakan Câmedâr'], 'Candarlar saray kapılarını bekleyen ve saltanat çadırını koruyan seçkin muhafızlardır; başlarındaki komutana Emir-i Candar denilirdi.'),
  ('Türkiye Selçuklu Devleti\'nde Antalya, Alanya ve Sinop gibi kıyı bölgelerinin valiliğini ve deniz kuvvetlerinin başkomutanlığını yürüten görevliye hangi unvan verilmiştir?', 'Melikü\'s-Sevâhil', ['Kara ordularının merkez kanadını yöneten Beylerbeyi', 'Fırat ve Dicle üzerindeki sal taşımacılığını denetleyen Kelekçi', 'Kervan yollarındaki derbent geçitlerini koruyan Rahdâr'], '\'Sahillerin Meliki\' anlamına gelen Melikü\'s-Sevâhil (veya Emirü\'s-Sevâhil / Reisü\'l-Bahr), Selçuklu donanmasının amirali ve sahil eyaletlerinin askeri yöneticisidir.'),
  ('Türkiye Selçuklu Devleti\'nin özellikle 13. yüzyılın ilk yarısında Gürcü, Frenk (Avrupalı) ve Rum paralı askerleri de ordusunda istihdam etmiş olması aşağıdakilerden hangisinin göstergesidir?', 'Zenginleşen devlet hazinesinin nakit gücüyle profesyonel askeri çeşitliliğe yöneldiğinin', ['Anadolu\'daki Türk nüfusunun askerlik mesleğini tamamen terk ettiğinin', 'İkta sisteminin I. Kılıçarslan devrinde bütünüyle yürürlükten kaldırıldığının', 'Haçlı devletleriyle kalıcı bir siyasi federasyon çatısı altında birleşildiğinin'], 'Ticaret gelirleriyle hazinesi güçlenen Türkiye Selçukluları, özellikle II. Gıyaseddin Keyhüsrev ve öncesinde Hristiyan Frenk, Gürcü ve Rum ücretli birlikleri de yardımcı kuvvet olarak kullanmıştır; ancak Kösedağ\'da bu birliklerin bağlılığı zayıf kalmıştır.'),
  ('Selçuklu sınır bölgelerine yerleştirilen yarı göçebe Türkmen boylarının \'Uç Teşkilatı\' çatısı altında örgütlenmesi devlete öncelikle hangi stratejik faydayı sağlamıştır?', 'Hem sınırların sürekli korunmasını hem de yerleşik tarım alanlarının göçebe baskısından uzak tutulmasını', ['Türkmen boylarının deniz ticaretiyle uğraşarak Venedik filosunu Akdeniz\'den çıkarmasını', 'Bütün göçebe çadırlarının vergiden muaf tutularak merkez başkent Konya\'ya taşınmasını', 'Bizans imparatorlarıyla yapılan tüm ticaret antlaşmalarının uç beylerince feshedilmesini'], 'Uç bölgelerine yerleştirilen savaşçı Türkmenler gaza ruhuyla Bizans ve Ermeni sınırlarını yıpratırken, İç Anadolu\'daki yerleşik köylü ile göçebe sürüleri arasındaki arazi sürtüşmeleri de azaltılmıştır.'),
  ('Selçuklu ikta düzeninde toprağı işleyen köylünün (reayanın) ikta sahibine karşı konumu aşağıdakilerden hangisinde hukuki açıdan doğru tanımlanmıştır?', 'İkta sahibinin kölesi olmayıp kanunla belirlenen vergisini ödeyen hür kiracıdır', ['Toprakla birlikte başka bir sipahiye alınıp satılabilen serf statüsündedir', 'İkta sahibinin özel mahkemesinde yargılanan ve mülk edinmesi yasak olan işçidir', 'Ürettiği tahılın tamamını sipahiye teslim edip yalnızca boğaz tokluğuna çalışır'], 'Orta Çağ Avrupa feodalitesinin aksine Selçuklu ikta sisteminde köylü hürdür; sipahi toprağın mülk sahibi değil yalnızca devlet adına vergi toplayan görevlidir.'),
  ('Selçuklu adalet teşkilatında kamu düzenini bozanlara, devlet güvenliğine başkaldıranlara ve kanunlara uymayan memurlara ilişkin \'örfi davalara\' bakan üst düzey yargı görevlisi hangisidir?', 'Emir-i Dâd', ['Vakıf şartnamelerinin uygulanmasını denetleyen Nâzır-ı Evkaf', 'Yabancı elçilerin diplomatik dokunulmazlığını koruyan Tercümanbaşı', 'Miras kalan malların varisler arasındaki payını hesaplayan Feraizci'], 'Şer\'i hukukun yanında Türk devlet geleneğinden gelen örfi hukuku uygulayan Divan-ı Mezalim ve örfi yargının yürütücüsü Emir-i Dâd\'dır; gerektiğinde veziri dahi tutuklayabilecek yetkiye sahipti.'),
  ('Selçuklu hükümdarlık sembolleri arasında yer alan ve sultanın saray kapısında günde beş namaz vaktinde (veya üç vakitte) çalınan askeri mızıka takımına ne ad verilirdi?', 'Nevbet', ['Savaşta hükümdarın başı üzerinde tutulan ipek şemsiye Çetr', 'Halifenin sultana gönderdiği altın işlemeli tören giysisi Hil\'at', 'Saray kabul salonuna serilen hanedan armalı ipek seccade Gâşiye'], 'Kös, davul, zurna, nakkare ve borulardan oluşan hükümdarlık bandosuna \'Nevbet\' (Tabılhane) denir; kapıda beş vakit nevbet vurulması bağımsız sultanlığın en önemli alametlerindendir.'),
  ('Türkiye Selçuklu Devleti\'nde ilk madenî paranın (bakır sikke) I. Mesud devrinde, ilk gümüş ve altın paraların ise II. Kılıçarslan devrinde basılmış olması iktisadi açıdan nasıl yorumlanır?', 'Siyasi istikrarın pekişmesiyle Anadolu ekonomisinin takas ve yabancı sikkeden milli para hacmine yükseldiği biçiminde', ['Anadolu\'da 12. yüzyıl ortasına kadar hiçbir altın veya gümüş madeninin bilinmediği şeklinde', 'Bizans altın sikkelerinin Selçuklu pazarlarında kullanılmasının idamla cezalandırıldığı biçiminde', 'İlk Selçuklu sultanlarının para kullanımını İslam hukukuna aykırı buldukları şeklinde'], 'Kuruluş ve Haçlı savaşları yıllarında Bizans ve İslam paraları tedavüldeyken, I. Mesud bakır parayı, siyasi birliği sağlayan ve ticareti büyüten II. Kılıçarslan ise gümüş dirhem ve altın dinarı bastırmıştır.'),
  ('1176 Miryokefalon Savaşı\'nda Bizans İmparatoru Manuel Komnenos\'un ağır kuşatma makineleri ve binlerce arabalık ikmal konvoyuyla ilerlemesini Sultan II. Kılıçarslan hangi askeri taktikle felakete çevirmiştir?', 'Bizans ordusunu sarp ve dar geçide çekip iki yamaçtan ok yağmuru ve pusuya düşürerek', ['Konya Ovası\'ndaki nehir bentlerini yıkarak Bizans kampını su altında bırakarak', 'Karadeniz\'den gemilerle İstanbul\'a çıkarma yapıp imparatoru geri dönmeye zorlayarak', 'Kış ortasında kalelere kapanıp Bizans ordusunun salgın hastalıktan dağılmasını bekleyerek'], 'II. Kılıçarslan önce geri çekilip su ve otlakları tahrip ederek yıprattığı hantal Bizans ordusunu Eğirdir/Düzbel yakınlarındaki sarp Miryokefalon geçidinde kıstırarak kuşatma makineleriyle birlikte imha etmiştir.'),
  ('I. Alaeddin Keykubad\'ın Mengüceklilerin Erzincan koluna (1228) ve Harput Artuklularına (1234) son vererek Doğu Anadolu\'daki özerk Türk beyliklerini doğrudan merkeze bağlamasının temel nedeni nedir?', 'Moğol tehlikesine karşı doğu sınırındaki kaleleri tek elden güçlü biçimde savunmak', ['Doğu Anadolu\'daki tüm şehirlerin nüfusunu Antalya ve Alanya limanlarına taşımak', 'Bölgedeki gümüş madenlerini kapatarak Venedik altını kullanımına geçmek', 'Gürcistan Krallığı ile yaptığı antlaşma gereği sınır kalelerini silahsızlandırmak'], 'Doğudan yaklaşan Moğol fırtınasını gören I. Alaeddin Keykubad, küçük ve gevşek bağlı beyliklerin Moğolları durduramayacağını bildiğinden Erzincan, Kemah, Şebinkarahisar, Harput ve Ahlat\'ı doğrudan merkez ordusunun denetimine almıştır.'),
  ('1225 yılında Abbasi Halifesi Zâhir-Billah adına ünlü mutasavvıf Şihabüddin Sühreverdi\'nin Konya\'ya gelerek Sultan I. Alaeddin Keykubad\'a menşur, kılıç ve hil\'at sunması hukuken ne ifade eder?', 'Selçuklu sultanının meşruiyetinin İslam dünyasının dini liderince resmen tasdik edilmesini', ['Türkiye Selçuklu Devleti\'nin bağımsızlığını yitirip Bağdat valiliğine indirgenmesini', 'Halifenin tüm dünyevi ve dini yetkilerini süresiz olarak Konya sarayına devretmesini', 'Anadolu\'daki örfi hukuk kurallarının kaldırılıp yalnız Arap örfünün benimsenmesini'], 'Orta Çağ Türk-İslam devlet geleneğinde Abbasi halifesinden menşur, sancak ve hil\'at almak, hükümdarın İslam dünyası ve kendi tebaası nezdindeki meşruiyetini ve prestijini en üst düzeye çıkarırdı.'),
  ('1243 Kösedağ Savaşı öncesinde tecrübeli komutanların Sivas surları gerisinde savunma yapıp Moğolları yıpratma önerisini reddederek genç komutanların kışkırtmasıyla açık alanda hücum emri veren sultan kimdir?', 'II. Gıyaseddin Keyhüsrev', ['Babailer İsyanı\'ndan önce Kayseri\'de vefat eden I. Alaeddin Keykubad', 'Üçlü saltanat döneminde Moğol başkentine giden IV. Kılıçarslan', 'Memlük Sultanı Baybars\'ı Anadolu\'ya davet eden III. Gıyaseddin Keyhüsrev'], 'Sayıca ve donanımca Moğollardan üstün olan Selçuklu ordusu, genç ve tecrübesiz II. Gıyaseddin Keyhüsrev\'in ihtiyatlı vezir Mühezzibüddin Ali ve yaşlı emirleri dinlemeyip Kösedağ geçidinden plansızca inmesi yüzünden sahte ricat tuzağına düşmüştür.'),
  ('13. yüzyılın ikinci yarısında Türkiye Selçuklu vezirliği yapan, Moğol baskısına rağmen Konya, Sivas, Kayseri ve Akşehir\'de çok sayıda medrese, cami ve külliye inşa ettirdiği için \'Ebü\'l-Hayrât\' (Hayırların Babası) unvanıyla anılan devlet adamı kimdir?', 'Sahip Ata Fahreddin Ali', ['Alanya Tersanesi ve Kızılkule\'nin mimarlığını üstlenen Ebu Ali Reha', 'Kırşehir\'de gökbilim medresesi kuran Nureddin Cacabey', 'Tokat\'ta Gök Medrese\'yi inşa ettiren Muineddin Süleyman Pervane'], 'Uzun yıllar Selçuklu vezirliği (Sahip) görevinde bulunan Fahreddin Ali; Konya İnce Minareli Medrese, Sahip Ata Külliyesi ve Sivas Gök Medrese gibi başyapıtları kişisel servetiyle vakfettiği için \'Ebü\'l-Hayrât\' diye anılmıştır.'),
  ('Türkiye Selçuklu maliyesinde şehir pazarlarında alınıp satılan mallar ile gümrük kapılarından geçen ticari yüklerden tahsil edilen örfi vergiye ne ad verilirdi?', 'Bâc-ı Bâzâr', ['Maden ocaklarından çıkarılan cevherin beşte biri olan Humus', 'Evlenen çiftlerin kadı siciline ödediği Arûsâne resmi', 'Sahipsiz kalarak hazineye devredilen Beytülmal mirası'], 'Şehir çarşılarında ve transit geçişlerde tüccarlardan alınan ticaret ve pazar vergisine \'bac\' (Moğol devrinde \'tamga\') adı verilmekteydi.'),
  ('1147 yılındaki II. Haçlı Seferi sırasında Alman İmparatoru III. Konrad\'ın ağır zırhlı şövalye ordusunu Eskişehir (Dorileon) yakınlarında bozguna uğratan Türkiye Selçuklu hükümdarı kimdir?', 'Sultan I. Mesud', ['İznik\'i Haçlılara karşı savunan Sultan I. Kılıçarslan', 'Antalya limanını Venediklilere açan I. Gıyaseddin Keyhüsrev', 'Harzemşahları Erzincan\'da durduran I. Alaeddin Keykubad'], 'I. Kılıçarslan\'ın 1097\'de I. Haçlılara yenildiği Dorileon mevkiinde elli yıl sonra oğlu Sultan I. Mesud (Ekim 1147), Alman İmparatoru III. Konrad\'ın ordusunun onda dokuzunu imha ederek tarihi bir rövanş almıştır.'),
  ('1190 yılında III. Haçlı Seferi\'ne çıkan Alman İmparatoru Friedrich Barbarossa\'nın Konya önlerine kadar ilerlemesine rağmen bu seferin Kudüs ve Anadolu açısından etkisiz kalmasının ani sebebi nedir?', 'İmparator Barbarossa\'nın Silifke\'deki Göksu Irmağı\'nda boğulmasıyla ordusunun dağılması', ['Bizans donanmasının Çanakkale Boğazı\'nı kapatarak Almanlara erzak göndermemesi', 'Selçuklu donanmasının Akdeniz\'de Alman taşıma gemilerinin tamamını batırması', 'Papa\'nın Alman imparatorunu aforoz ederek şövalyeleri ülkesine geri çağırması'], 'Yaşlı Sultan II. Kılıçarslan\'ın oğulları arasındaki anlaşmazlıktan yararlanarak Konya\'dan geçen Friedrich Barbarossa, 10 Haziran 1190\'da Göksu (Saleph) Nehri\'ni geçerken boğulunca büyük Alman Haçlı ordusu paniğe kapılıp dağılmıştır.'),
  ('Sultan Rükneddin Süleymanşah\'ın 1196-1204 yılları arasındaki kısa hükümdarlığında Türkiye Selçuklu siyasi tarihine yaptığı en önemli katkı aşağıdakilerden hangisidir?', 'Kardeşler arasındaki bölünmüşlüğe son verip Saltuklu topraklarını katarak Anadolu birliğini yeniden kurması', ['Kırım yarımadasındaki tüm Kıpçak şehirlerini Selçuklu sınırlarına dahil etmesi', 'Moğol hükümdarı Cengiz Han ile saldırmazlık ve ticaret paktı imzalaması', 'Başkenti Konya\'dan yeniden Marmara kıyısındaki İznik kentine taşıması'], 'II. Kılıçarslan\'ın ülkeyi 11 oğluna paylaştırmasıyla doğan parçalanmayı ortadan kaldıran Rükneddin Süleymanşah, devleti yeniden tek merkezde toplamış ve 1202\'de Erzurum\'u (Saltuklular) ülkeye katmıştır.'),
  ('Selçuklu ordusunda hükümdarın savaş esnasında silahlarını taşıyan, kılıç ve ok-yay takımlarından sorumlu olan, aynı zamanda saray silah depolarını (cebehane/zerdühane) denetleyen görevli kimdir?', 'Emir-i Silâh', ['Hükümdarın kıyafetlerini ve kaftanlarını muhafaza eden Câmedâr', 'Sarayın temizlik ve döşeme işlerini idare eden Ferrâş', 'Yol kavşaklarındaki posta atlarını değiştiren Ulakbaşı'], 'Sultanın en güvendiği has köleleri arasından seçilen Emir-i Silâh (Silahdâr), törenlerde hükümdarın kılıcını taşır ve sarayın silah imalathane/depolarına nezaret ederdi.'),
  ('Türkiye Selçuklu sultanlarının yaz aylarında Beyşehir Gölü kıyısındaki Kubadabad\'a veya Kayseri\'deki Keykubadiye\'ye, kış aylarında ise Alanya ve Antalya\'ya gitmeleri yönetim geleneği açısından nasıl açıklanır?', 'Türklerin yaylak-kışlak hareketliliğinin yerleşik saray ve başkent kültürüne uyarlanmasıyla', ['Konya kalesinin her yıl kış aylarında sel baskınları yüzünden oturulamaz hale gelmesiyle', 'Devlet hazinesinin tek bir şehirde saklanmasının şer\'i hukukça yasaklanmış olmasıyla', 'Sınır valilerinin başkente gelmesi yasaklandığından sultanın her vilayeti tek tek gezmesiyle'], 'Merkez Konya olmakla birlikte sultanların mevsime göre Kayseri, Beyşehir ve Alanya\'daki saraylar arasında divanla birlikte yer değiştirmesi hem Oğuz yaylak-kışlak mirasını hem de ülkeyi yakından denetleme siyasetini yansıtır.'),
  ('Kösedağ Savaşı\'ndan sonra İlhanlıların Türkiye Selçuklu tahtını tek bir güçlü sultana bırakmayıp rakip kardeşler arasında Kızılırmak sınır olmak üzere ikiye bölmelerinin (II. İzzeddin Keykavus ve IV. Kılıçarslan) temel amacı nedir?', 'Böl ve yönet politikasıyla Selçukluların toparlanmasını önleyip daha fazla haraç koparmak', ['Batı Anadolu\'daki Hristiyan nüfusa ayrı bir anayasal yönetim bölgesi kazandırmak', 'Doğu ve Batı Anadolu arasındaki iklim farkına göre tarımsal uzmanlaşmayı artırmak', 'Her iki şehzadenin de Moğol ordusuna eşit sayıda gemi üretmesini sağlamak'], 'İlhanlılar rakip Selçuklu şehzadelerini birbirine karşı koz olarak kullanmış, taht onayı (yarlığ) karşılığında her iki taraftan da ağır vergi ve hediyeler alarak merkezi otoriteyi felç etmiştir.'),
  ('Türkiye Selçuklu Devleti\'nin 12. yüzyıl ortalarında Danişmendlilerle girdiği üstünlük mücadelesinde Sultan II. Kılıçarslan\'ın Malatya ve Sivas\'ı ilhak etmesi Anadolu\'da hangi jeopolitik değişimi sağlamıştır?', 'Anadolu Türk siyasi birliği liderliğinin Danişmendlilerden kesin olarak Türkiye Selçuklularına geçmesini', ['Doğu Karadeniz\'deki Trabzon Rum Devleti\'nin yıkılarak Sinop\'a bağlanmasını', 'Fırat Nehri doğusundaki tüm Artuklu kalelerinin Eyyubilere terk edilmesini', 'İpek Yolu\'nun kuzey kolunun Anadolu\'dan çıkarak Kafkasya bozkırlarına kaymasını'], 'Kuruluş yüzyılında zaman zaman Selçuklulardan daha güçlü olan Danişmendlilerin 1175-1178 arasında II. Kılıçarslan tarafından ortadan kaldırılmasıyla Anadolu\'nun tek hâkim gücü Türkiye Selçukluları olmuştur.'),
  ('Selçuklu sarayında devlet hazinesinden ayrı tutulan ve doğrudan sultanın şahsi mülklerinden, hediyelerden ve has arazilerden beslenen özel hazineye ne ad verilmiştir?', 'Hazine-i Hâssa', ['Yetim çocukların mallarının saklandığı Sandık-ı Eytâm', 'Esnaf loncalarının yardımlaşma fonu olan Orta Sandığı', 'Savaş esirlerinin fidye bedellerini toplayan Beytü\'l-Üserâ'], 'Devletin genel maliyesini oluşturan Hazine-i Âmire\'nin yanında hükümdarın şahsi gelirlerinin toplandığı \'Hazine-i Hâssa\' bulunur; dar zamanlarda veya büyük kale inşaatlarında sultan buradan devlet bütçesine destek verirdi.'),
  ('I. İzzeddin Keykavus\'un Kıbrıs Haçlı Kralı Hugo ile mektuplaşarak karşılıklı serbest ticaret ve korsanlığa karşı ortak güvence antlaşması imzalaması Türkiye Selçuklu dış politikasının hangi yönünü kanıtlar?', 'Dini farklılıkların uluslararası deniz ticaretini geliştiren pragmatik antlaşmalara engel olmadığını', ['Türkiye Selçuklularının Akdeniz\'deki tüm limanlarını Haçlı şövalyelerine kiraladığını', 'Kıbrıs Krallığı\'nın Selçuklu Devleti\'ne bağlı Müslüman bir emirliğe dönüştüğünü', 'Konya sarayının Venedik ve Ceneviz gemilerine Akdeniz\'i tamamen kapattığını'], 'Selçuklu sultanları Haçlı dünyasıyla gerektiğinde savaşmış, ancak barış dönemlerinde Kıbrıs Haçlı Krallığı ve Venedik ile son derece akılcı ticaret ahidnameleri imzalayarak Anadolu ekonomisini büyütmüşlerdir.'),
  ('1243 Kösedağ Savaşı\'ndan sonra İlhanlıların Anadolu\'daki mali kaynakları doğrudan denetlemek için Selçuklu vezirlerinin yanına İran\'dan gönderdikleri sivil-mali memurlar ve askeri valiler neye yol açmıştır?', 'Çift başlı yönetim kargaşasına ve halkı ezen ağır vergi soygununa', ['Anadolu\'da tarımsal üretimin beş yıl içinde on katına çıkmasına', 'Türkmen beylerinin İlhanlı ordusunda başkomutanlığa getirilmesine', 'Selçuklu medreselerindeki vakıf gelirlerinin iki kat artırılmasına'], 'İlhanlıların atadığı \'basgak/şahne\' adlı askeri valiler ile yüksek faizli borç ve ağır \'kopçur/tamga\' vergileri dayatan maliyeciler Selçuklu otoritesini aşındırıp halkı yoksullaştırmıştır.'),
  ('11. yüzyıl sonunda I. Kılıçarslan\'ın kayınpederi İzmir Beyi Çaka Bey\'i Bizans İmparatoru I. Aleksios Komnenos\'un diplomatik kışkırtmaları sonucu ziyafette öldürtmesi kimin stratejik işine yaramıştır?', 'Hem denizden hem karadan kuşatılma tehdidinden kurtulan Bizans İmparatorluğu\'nun', ['Ege adalarındaki ticaret üslerini Türklere devretmek isteyen Venedik Cumhuriyeti\'nin', 'Anadolu\'da Haçlılara karşı deniz filosu arayan Danişmendli Beyliği\'nin', 'Trakya üzerinden İstanbul surlarına yürüyen Peçenek Türklerinin'], 'Bizans diplomasisinin \'Türk\'ü Türk\'e kırdırma\' tuzağına düşen genç I. Kılıçarslan, Çaka Bey\'i ortadan kaldırınca Türk denizciliği Ege\'de iki yüzyıllık bir duraklama yaşamış ve Bizans rahat nefes almıştır.'),
  ('Kayseri\'nin Pınarbaşı ilçesi Pazarören yakınlarında her yıl bahar aylarında kırk gün boyunca kurulan ve Rus, Kıpçak, İranlı, Suriyeli ile Avrupalı tüccarların kürkten baharata dek mal takas ettiği uluslararası fuar hangisidir?', 'Yabanlu Pazarı', ['Konya iç kalesinin eteklerinde sadece Cuma günleri açılan At Pazarı', 'Sivas Gök Medrese yakınında tahıl fiyatlarının belirlendiği Buğday Meydanı', 'Antalya sur kapısında Venedik gemilerinin demirlediği İskele Bedesteni'], 'Kayseri-Elbistan-Sivas kavşağındaki Yabanlu Pazarı, 13. yüzyılda Doğu ile Batı tüccarlarının buluştuğu en büyük milletlerarası Anadolu panayırıdır.'),
  ('Venedik ve Kıbrıs Haçlı Krallığı ile imzalanan ahidnamelerde gümrük vergisi oranının %10-20 seviyelerinden %2 gibi çok düşük bir orana çekilmesinin ardındaki ekonomik strateji nedir?', 'Sürümden kazanarak Akdeniz ticaret gemilerini Anadolu limanlarına çekmek', ['Yerli Müslüman tüccarların deniz ticaretine girmesini tamamen engellemek', 'Gümrük memurlarının maaş ödeneklerini ortadan kaldırıp bürokrasiyi küçültmek', 'İtalyan cumhuriyetlerinden yüksek faizli dış borç alabilmek için taviz vermek'], 'Düşük gümrük tarifesi sayesinde Mısır ve Suriye yerine Antalya-Alanya limanlarını tercih eden Avrupalı tüccarlar ticaret hacmini katlamış, artan kervan trafiği devlete çok daha yüksek toplam gelir sağlamıştır.'),
  ('Ahilik teşkilatının ahlaki kurallarını, sofrası-eli-kapısı açık olma ilkelerini, çıraklıktan ustalığa geçiş törenlerini ve esnaf adabını yazılı hale getiren tüzük niteliğindeki eserlere ne ad verilir?', 'Fütüvvetnâme', ['Devlet adamlarına siyaset sanatını öğütleyen Siyasetnâme', 'Yabancı ülkelere giden elçilerin izlenimlerini anlatan Sefaretnâme', 'Padişah düğünlerini ve şenliklerini tasvir eden Sûrnâme'], 'Abbasi Halifesi Nâsır-Lidînillah dönemindeki fütüvvet geleneğiyle de beslenen Ahiliğin anayasası niteliğindeki görgü ve meslek kuralları kitaplarına \'Fütüvvetnâme\' (ör. Burgazi Fütüvvetnamesi) denir.'),
  ('Çıraklık ve kalfalık eğitimini başarıyla tamamlayıp mesleki yeterliliğini kanıtlayan bir Ahi gencinin, ustalar meclisi huzurunda beline kuşak bağlanarak kendi dükkânını açma izni aldığı törene ne denir?', 'Şed kuşatma töreni', ['Esnaf loncasından geçici süreyle uzaklaştırma olan Yolsuz ilan etme', 'Yeni açılan çarşının bereketi için düzenlenen Dua kubbesi merasimi', 'Hükümdarın esnaf temsilcilerine kaftan giydirdiği Hil\'at töreni'], 'Ahi zaviyesinde ustaların onayıyla kalfanın beline peştamal/kuşak (\'şed\') bağlanması, kişinin hem mesleki hem ahlaki açıdan \'usta\' (icazet sahibi) olduğunun resmi ilanıdır.'),
  ('Esnaf birliklerinde üyelerin ödediği aidatlar ve bağışlarla oluşturulan, yaşlanan, hastalanan ya da iş yeri yanan esnafa karşılıksız destek veya faizsiz kredi sağlayan yardımlaşma fonu hangisidir?', 'Orta Sandığı', ['Askeri sefer masrafları için halktan toplanan İمدâdiyye Akçesi', 'Gümrük kapılarında biriken vergilerin tutulduğu Bac Sandığı', 'Saray mutfağının erzak alımlarını karşılayan Matbah Hazinesi'], 'Sosyal güvenlik kurumu gibi işleyen Ahi \'Orta Sandığı\', üyelerini tefecilerin eline düşmekten korumuş, cenaze, hastalık ve çırak sermayesi giderlerini karşılamıştır.'),
  ('Kayseri\'de 1206 yılında Sultan I. Gıyaseddin Keyhüsrev tarafından kız kardeşi vasiyetiyle yaptırılan \'Gevher Nesibe Darüşşifası ve Gıyasiye Tıp Medresesi\'ni tıp tarihinde ayrıcalıklı kılan yapısal özelliği nedir?', 'Uygulamalı hastane ile teorik tıp okulunun yan yana ikiz bina olarak bütünleşik kurulması', ['Yalnızca savaşta yaralanan saray muhafızlarının tedavisine tahsis edilmiş olması', 'Anadolu\'da hekimlerin hastalardan yüksek ücret aldığı ilk özel klinik olması', 'Bütün derslerinin Latince tıp kitapları üzerinden Avrupalı hekimlerce verilmesi'], '\'Çifte Medrese\' olarak da bilinen Kayseri Gevher Nesibe Külliyesi\'nde tıp öğrencileri bir kanatta teorik ders alırken bitişik şifahanede usta hekimlerin yanında hasta başı klinik uygulama yapıyorlardı.'),
  ('Sivas\'ta 1217 yılında Sultan I. İzzeddin Keykavus tarafından inşa ettirilen ve sultanın türbesini de barındıran \'Keykavus Darüşşifası\' Anadolu\'daki en büyük şifahane olmasının yanı sıra hangi tedavi yöntemiyle öne çıkmıştır?', 'Ruh ve sinir hastalarının su sesi ve musiki makamlarıyla ücretsiz tedavi edilmesiyle', ['Veba salgınlarına karşı çiçek aşısının ilk kez laboratuvar ortamında üretilmesiyle', 'Kırık kemiklerin platin çivilerle birleştirildiği cerrahi ameliyatların yapılmasıyla', 'Sadece şifalı kaplıca çamurlarının kullanıldığı kapalı yüzme havuzlarıyla'], 'Dört eyvanlı anıtsal planıyla en büyük Selçuklu hastanesi olan Sivas İzzeddin Keykavus Darüşşifası vakfiyesinde göz hekimi (kehhal), cerrah ve eczacıların yanında akıl hastalarına telkin ve su-müzik terapisi uygulandığı görülür.'),
  ('Yunus Emre\'nin aruz veznini de kullanarak kaleme aldığı ve nefsin terbiyesi, kibir, öfke ile cimrilikten arınma öğütlerini alegorik bir dille anlattığı mesnevi türündeki eseri hangisidir?', 'Risâletü\'n-Nushiyye', ['Tasavvufun dört kapı kırk makam ilkelerini açıklayan Makâlât', 'Yirmi beş bin beyitten oluşan hikâyeli tasavvuf klasiği Mesnevî', 'Oğuz Türklerinin kahramanlık destanlarını derleyen Dede Korkut Kitabı'], 'İlahilerinin toplandığı \'Dîvân\'ının yanı sıra Yunus Emre\'nin 1307-1308 yılında yazdığı \'Risâletü\'n-Nushiyye\' (Öğütler Kitabı), Anadolu Türkçesinin ilk ve en değerli ahlaki-tasavvufi mesnevilerindendir.'),
  ('Hacı Bektaş-ı Velî\'nin insanın olgunlaşma (insan-ı kâmil olma) sürecini \'Şeriat, Tarikat, Marifet ve Hakikat\' basamaklarından oluşan \'Dört Kapı Kırk Makam\' öğretisiyle anlattığı temel eseri hangisidir?', 'Makâlât', ['Mevlânâ\'nın sohbet notlarının bir araya getirildiği Fîhi Mâ Fîh', 'Sultan Veled\'in Türkçe beyitlere de yer verdiği İbtidânâme', 'Âşık Paşa\'nın Türk dilinin önemini savunduğu Garibnâme'], 'Horasan erenlerinden Hacı Bektaş-ı Velî\'nin \'Makâlât\' adlı eseri, Kur\'an ahlakını ve içsel arınmayı Dört Kapı Kırk Makam sistemiyle açıklayarak Anadolu tasavvufunun temel taşlarından biri olmuştur.'),
  ('Camiler ve medreseler gibi dini yapılarda insan ve hayvan tasvirlerinden kaçınılırken Kubadâbâd Sarayı çinilerinde ve şehir surlarında insan, melek, kartal, aslan ve burç figürlerinin bolca kullanılması neyi gösterir?', 'Sivil ve askeri mimaride Orta Asya Türk sembolizmi ile saray ikonografisinin özgürce yaşatıldığını', ['Saray çinilerinin tamamının İtalya\'daki Hristiyan atölyelerinden hazır ithal edildiğini', 'I. Alaeddin Keykubad döneminde İslamiyet öncesi Şamanizm inancına geri dönüldüğünü', 'Dini yapılarda taş ve çini süslemenin kadı kararlarıyla tamamen yasaklandığını'], 'Selçuklu sanatında ibadet mekânlarında geometrik, bitkisel (rumi-hatayi) ve yazı bezemeleri kullanılırken; saray, köşk, hamam ve kale burçlarında Türk hükümdarlık ve kozmoloji figürleri zengin biçimde işlenmiştir.'),
  ('Konya\'da 1251 yılında Emir Celaleddin Karatay tarafından yaptırılan \'Karatay Medresesi\'nin iç kubbesinde gökyüzündeki yıldızları simgeleyen firuze, lacivert ve siyah renkli geometrik kaplama hangi sanat dalının başyapıtıdır?', 'Mozaik çini sanatı', ['Ahşap parçaların çivisiz geçme tekniğiyle birleştirildiği Kündekârî', 'Altın tozunun suyla ezilip el yazması kenarlarına sürüldüğü Tezhip', 'Mermer blokların oyularak içine renkli taşlar gömüldüğü Kakmacılık'], 'Bugün Çini Eserler Müzesi olan Konya Karatay Medresesi\'nin kubbesini ve pandantiflerini kaplayan firuze-patlıcan moru-siyah yıldız ağları, Selçuklu çini mozaik sanatının doruk noktasıdır.'),
  ('Ceviz, abanoz ve şimşir gibi sert ağaçlardan küçük geometrik parçaların çivi ya da tutkal kullanılmaksızın birbirine geçmeli (zıvanalı) çatılmasıyla minber ve kapı kanatları üretilen geleneksel Türk ahşap sanatına ne ad verilir?', 'Kündekârî', ['Bakır kapların üzerinin kalemle kazınarak desenlendiği Kazıma', 'Sırlı tuğlaların farklı açılarla dizilerek yazı oluşturulduğu Bânâî tekniği', 'Kitap ciltlerinin deri kapaklarına altın kalıpla basılan Şemse sanatı'], 'Konya Alaeddin Camii minberi (1155), Aksaray ve Siirt Ulu Cami minberlerinde görülen gerçek \'kündekârî\' tekniği, ahşabın nem ve sıcaklıkla çatlayıp eğrilmesini yüzyıllar boyu engellemiştir.'),
  ('Konya Alaeddin Camii ve Beyşehir Eşrefoğlu Camii\'nde keşfedilen 13. yüzyıl Selçuklu halılarının dünya dokuma tarihindeki önemini belirleyen başlıca teknik ve sanatsal özellik nedir?', 'Gördes (Türk) çift düğümü, geometrik yıldız-sekizgen motifleri ve kufi bordür yazıları taşıması', ['Tamamen Çin ipeği ve altın tellerle dokunup yalnızca duvar panosu olarak kullanılması', 'Üzerlerinde hükümdarların gerçekçi yağlıboya portrelerine benzer figürlerin yer alması', 'Düğümsüz düz kilim tekniğiyle keten liflerinden tek renkli olarak üretilmiş bulunması'], 'Marco Polo\'nun \'dünyanın en güzel ve en ince halıları Türkiye\'de dokunur\' diye övdüğü Selçuklu halıları, sağlam Türk (Gördes) düğümü ve anıtsal kufi kenar sularıyla Orta Asya Pazırık halı geleneğinin Anadolu\'daki halkasıdır.'),
  ('1271 yılında Sivas\'ta üç ayrı bani tarafından aynı yıl inşa ettirilen \'Gök Medrese, Buruciye Medresesi ve Çifte Minareli Medrese\'nin aynı kentte toplanması Sivas hakkında neyi kanıtlar?', 'Moğol baskısı döneminde dahi Sivas\'ın ticari zenginliğini ve yükseköğretim cazibesini koruduğunu', ['Konya ve Kayseri\'deki tüm medreselerin deprem yüzünden kapatılıp Sivas\'a taşındığını', 'İlhanlı hükümdarlarının Anadolu\'da yalnızca Sivas şehrinde bina yapılmasına izin verdiğini', 'Bu üç medresenin de aslında askeri kışla olarak yapılıp sonradan okula çevrildiğini'], '1271 yılında Vezir Sahip Ata Fahreddin Ali\'nin Gök Medrese\'yi, Muzaffereddin Burucirdî\'nin Buruciye\'yi ve İlhanlı Veziri Şemseddin Cüveynî\'nin Çifte Minareli Medrese\'yi Sivas\'ta yaptırması kentin görkemli kültür ve ticaret potansiyelini belgeler.'),
  ('Konya\'da 1242 yılında Emir Bedreddin Muslih tarafından fıkıh eğitimi için yaptırılan ve açık avlusunun iki katlı revakları ile eyvanındaki çini kaplamalarından ötürü bu adı alan medrese hangisidir?', 'Sırçalı Medrese', ['Taş kapısındaki yüksek kabartmalarla tanınan İnce Minareli Medrese', 'Sivas merkezde mermer taç kapısıyla yükselen Gök Medrese', 'Erzurum surlarının hemen yanında inşa edilen Yakutiye Medresesi'], 'Tusenli Mimar Muhammed bin Muhammed bin Osman\'ın eseri olan Konya Sırçalı Medrese, açık avlulu ve iki eyvanlı plan şemasının yanı sıra \'sırça\' (çini) bezemeleriyle ünlüdür.'),
  ('Kervansaraylarda revaklı açık avlunun ortasında dört kemerli ayaklar üzerinde yükselen küçük kare planlı yapı (\'köşk mescit\'), ibadet işlevinin yanında hangi sembolik ve pratik özelliği taşır?', 'Hayvan ve yük kalabalığından yalıtılmış temiz, vakur ve merkezi bir ibadet mekânı sunması', ['Sadece hükümdar ve vezirlerin konakladığı gizli hazine dairesi olarak kullanılması', 'Kervanlardan alınan gümrük altınlarının tartıldığı darphane odası işlevi görmesi', 'Gözcü askerlerin dumanla haberleşmek için ateş yaktığı fener kulesi olması'], 'Aksaray ve Kayseri Sultan Hanları ile Ağzıkara Han\'da avlu zeminindeki deve, at ve yük hareketliliğinden merdivenlerle koparılan \'köşk mescit\', hem temizliği korur hem de avlunun estetik odak noktasını oluşturur.'),
  ('Erzurum\'da 13. yüzyıl sonlarında inşa edilen ve Anadolu\'nun en büyük medreselerinden biri olan \'Çifte Minareli Medrese\' (Hatuniye) arka cephesindeki kümbeti ve ön yüzündeki hangi iki bezeme motifiyle simgeleşmiştir?', 'Hurma/hayat ağacı, çift başlı kartal ve ejder kabartmalı pano süslemeleriyle', ['Güneş sistemindeki gezegenlerin bakır levhalarla işlendiği zodyak kuşağıyla', 'Bizans imparatorlarıyla yapılan barış antlaşmasının Grekçe mermer metniyle', 'Yelkenli kadırga ve çapa figürlerinden oluşan denizcilik armalarıyla'], 'Erzurum Çifte Minareli Medrese\'nin taç kapı yan nişlerinde yükselen hayat ağacı, kökündeki çifte ejder ve tepesindeki çift başlı kartal kabartmaları Türk kozmolojisinin taş üzerindeki en güçlü ifadesidir.'),
  ('İlhanlı Hükümdarı Olcaytu Hüdabende devrinde Emir Cemaleddin Hoca Yakut tarafından 1310 yılında Erzurum\'da yaptırılan ve orta avlusunu örten mukarnaslı tonozu ile silindirik tuğla minaresiyle tanınan yapı hangisidir?', 'Yakutiye Medresesi', ['Amasya\'da Gökmedrese Camii adıyla bilinen Torumtay Külliyesi', 'Tokat merkezde Pervane Süleyman\'ın kurduğu Gök Medrese', 'Çankırı\'da yılan kabartmasıyla tanınan Atabey Ferruh Şifahanesi'], 'Kapalı avlulu medrese geleneğinin Doğu Anadolu\'daki görkemli temsilcisi olan Erzurum Yakutiye Medresesi (1310), pars ve kartal kabartmalı panoları ile çini bezemeli minaresiyle ünlüdür.'),
  ('Kastamonu, Ankara ve Konya yaylalarında yetiştirilen tiftik keçisi yünü (\'sof\'), safran, kitre zamkı, halı, deri ve bakır kapların Antalya-Sinop limanlarından dışarı satılması Türkiye Selçuklu ekonomisi hakkında neyi kanıtlar?', 'Yalnız transit geçiş ülkesi olmayıp yerli tarım, hayvancılık ve sanayi ürünleri ihraç ettiğini', ['İç pazarın ihtiyacını karşılayamadığı için gıda maddelerini dışarıdan ithal ettiğini', 'Madencilik ve dokumacılığın yalnızca yabancı Cenevizli ustalarca yürütüldüğünü', 'Göçebe Türkmenlerin şehir ekonomisine hiçbir hammadde katkısı sağlamadığını'], 'Anadolu hem Doğu-Batı baharat/ipek transit ticaretinden kazanç sağlamış hem de Türkmen sürülerinden gelen yün, tiftik, deri ve Ahi atölyelerinde işlenen mamul mallarla dış ticaret fazlası vermiştir.'),
  ('Gümüşhane, Bayburt, Ulukışla (Lülüe) ve Gümüşhacıköy gibi yerleşimlerin 13. yüzyılda hızla gelişip darphane merkezlerine dönüşmesinde belirleyici olan iktisadi etken nedir?', 'Zengin gümüş madenlerinin işletilerek yüksek ayarlı Selçuklu dirhemlerinin basılması', ['Deniz aşırı gemi yapımı için geniş sedir ormanlarına sahip olmaları', 'Yabancı elçiliklerin yazlık ikametgâh olarak bu kasabaları seçmesi', 'İpek böceği kozasının yalnızca bu yüksek yaylalarda üretilebilmesi'], 'Türkiye Selçuklu gümüş dirhemleri saflığı ve yüksek ayarıyla Akdeniz dünyasında itibar görmüş; Lülüe (Ulukışla), Gümüşsaray/Gümüşhane ve Bayburt gümüş ocakları devlet hazinesinin ana besleyicisi olmuştur.'),
  ('Ahilikte her meslek dalında ihtiyaçtan fazla dükkân açılmasını engelleyerek hem ustaların geçimini hem de ürün standardını koruyan iş yeri açma ruhsatı/hakkı uygulamasına ne ad verilmiştir?', 'Gedik sistemi', ['Üretilen mallara tavan fiyat belirleyen Narh tarifesi', 'Çarşı güvenliği için geceleri tutulan Pasban nöbeti', 'Devlet arazilerinin açık artırmayla kiralandığı Mukataa usulü'], 'Bir zanaat kolunda usta sayısı ve dükkân adedinin şehir nüfusunun talebine göre sınırlandırılmasına \'gedik\' denir; böylece yıkıcı rekabet ve kalitesiz üretim önlenmiştir.'),
  ('Konya, Kayseri, Niğde ve Divriği ulu camilerinde geniş ibadet alanını örtmek üzere birbirine paralel uzanan çok sayıda taş kemer ve payenin (veya ahşap direğin) kullanıldığı cami plan tipine mimarlık tarihinde ne denir?', 'Çok ayaklı (Ulu Cami / Kûfe tipi) plan şeması', ['Merkezi tek dev kubbenin yarım kubbelerle desteklendiği Klasik plan', 'Haç biçimli dört kolun kesişim yerinde kule yükselen Bazilikal plan', 'İbadet alanının açık havada sütunsuz bırakıldığı Namazgâh planı'], 'Erken Anadolu Türk mimarisinde (12.-13. yüzyıl) geniş cemaati aynı çatı altında toplamak için çok sayıda taş ayak veya ahşap sütun dizisinden oluşan \'çok ayaklı (hipostil) ulu cami\' şeması yaygın biçimde uygulanmıştır.'),
  ('Ahlat, Kayseri, Erzurum ve Konya\'da yükselen Selçuklu \'kümbet\'lerinde alt katta cenazenin toprağa verildiği \'mumyalık/kripta\' bölümü bulunurken üst katta kıble yönünde mihraplı bir mescit odası yer alması nasıl yorumlanır?', 'Ölüm hatırasını dua ve ibadet mekânıyla birleştiren iki katlı anıt mezar anlayışı olarak', ['Alt katın erzak deposu, üst katın ise gözetleme burcu olarak kullanıldığı biçiminde', 'Cenazenin toprağa gömülmeyip üst kattaki taş sandukanın içinde saklandığı şeklinde', 'Kümbetlerin başlangıçta kervansaray olarak yapılıp sonradan türbeye çevrildiği olarak'], 'Selçuklu kümbetlerinde gerçek mezar alt kattaki tonozlu cenazelik (mumyalık) odasındadır; merdivenle çıkılan üst kattaki sembolik sanduka ve mihrap ise ziyaretçilerin Kur\'an okuyup dua etmesi içindir.'),
  ('Ahi zaviyelerinde akşam iş bitiminde bir araya gelen genç çırak ve kalfalara Kur\'an, Türkçe-Farsça okuma yazma, hesap, görgü kuralları, musiki ve silah talimi öğretilmesi teşkilatın hangi yönünü ortaya koyar?', 'Yalnızca ekonomik bir lonca olmayıp yaygın halk eğitimi ve vatan savunması okulu olduğunu', ['Medreselerle rekabet ederek resmi din adamlarının halkla görüşmesini yasakladığını', 'Genç işçilerin aileleriyle görüşmesini engelleyen kapalı manastır hayatı kurduğunu', 'Devlet ordusuna alternatif olarak siyasi iktidarı ele geçirmeye hazırlandığını'], 'Ahilik gündüz iş başında mesleki beceri, akşam zaviyede ise okuryazarlık, ahlak, sofra adabı ve silah eğitimi vererek hem kamil insan hem de kriz anlarında (ör. Konya ve Ankara savunması) şehir muhafızı yetiştirmiştir.'),
  ('Niğde\'de Sancakbeyi Zeyneddin Beşare tarafından 1223 yılında Mimar Sıddık ve kardeşi Gazi\'ye yaptırılan, doğu taç kapısındaki taş örgüleri ve belirli saatte düşen \'taçlı kadın silüeti\' gölgesiyle ünlü yapı hangisidir?', 'Niğde Alaeddin Camii', ['Aksaray merkezde tuğla minaresiyle yükselen Eğri Minareli Cami', 'Kayseri kalesi yanında Hunat Mahperi Hatun\'un kurduğu Hunat Camii', 'Malatya Battalgazi\'de tuğla kubbeli eyvanıyla bilinen Ulu Cami'], 'Niğde İç Kalesi\'ndeki Alaeddin Camii (1223), mihrap önündeki üç kubbeli özgün planı ve doğu taç kapısında sabah güneşinde beliren taçlı genç kız gölgesiyle Selçuklu optik taş yontusunun Divriği ile birlikte en ünlü örneğidir.'),
  ('Ahilik teşkilatında üreticiden hammadde (örneğin ham deri, yün veya bakır külçe) satın alınırken büyük sermayeli ustaların malın tamamını kapatmasının yasaklanıp lonca eliyle tüm ustalara eşit/adil dağıtılması neyi engellemiştir?', 'Tekelleşmeyi (ihtikârı) önleyerek küçük esnafın hammadde darlığıyla ezilmesini', ['Kırsal kesimdeki köylülerin şehir pazarlarına mal getirmesini', 'Devletin gümrük kapılarında yabancı tüccarlardan vergi almasını', 'Çırakların kalfalık sınavına girerek yeni teknikler öğrenmesini'], 'Ahilikteki ortak hammadde tedariki ilkesi, zengin birkaç ustanın piyasayı kapatıp (stokçuluk/tekelcilik) diğer zanaatkârları işsiz bırakmasını önleyerek sosyal adaleti korumuştur.'),
  ('1243\'ten sonra Anadolu\'da basılan bazı Türkiye Selçuklu gümüş dirhemlerinde kelime-i tevhid ve sultan adının yanında \'Güneş ve Aslan\' (Şîr ü Hurşîd) tasvirinin yer aldığı ünlü sikkeler hangi hükümdara aittir?', 'II. Gıyaseddin Keyhüsrev', ['İlk bakır Selçuklu parasını kestiren Sultan I. Mesud', 'Kırım\'daki Suğdak limanını fetheden I. Alaeddin Keykubad', 'İznik\'te devleti kuran Kutalmışoğlu Süleymanşah'], 'II. Gıyaseddin Keyhüsrev\'in sevgili eşi Gürcü prensesi Gürcü Hatun\'a (Tamara) olan aşkının ve astrolojik Aslan burcundaki Güneş simgesinin hatırası olarak kestirdiği \'Şîr ü Hurşîd\' dirhemleri İslam nümismatiğinin en ünlü sikkeleridir.'),
  ('Amasya\'da 1267 yılında Vali Seyfeddin Torumtay tarafından yaptırılan \'Gökmedrese Camii ve Türbesi\' ile 1308\'de İlhanlılar devrinde İlduş Hatun adına kurulan \'Amasya Darüşşifası\'nda müzik aletleri ve cerrahi aletlerini konu alan ünlü tıp kitabını 15. yüzyıla taşırken Selçuklu mirasını devralan şifahane geleneği neyi kanıtlar?', 'Amasya\'nın Selçuklu\'dan Osmanlı\'ya uzanan kesintisiz bir klinik tıp ve kültür köprüsü olduğunu', ['Anadolu\'daki tüm tıp okullarının Kösedağ Savaşı sonrasında Amasya\'da birleştirildiğini', 'Şifahanelerde cerrahi müdahalenin yasaklanıp yalnızca bitkisel çaylar verildiğini', 'Amasya\'daki sağlık kurumlarının sadece Karadeniz gemicilerine hizmet verdiğini'], 'Selçuklu ve İlhanlı devrinde kurulan Amasya medrese ve darüşşifası, daha sonra Sabuncuoğlu Şerefeddin gibi büyük cerrahların yetişeceği köklü bir klinik tıp geleneği yaratmıştır.'),
  ('Mevlânâ\'nın altı ciltlik büyük eseri \'Mesnevî\'yi kaleme almasında kendisini teşvik eden ve Mevlânâ söylerken beyitleri gece gündüz yazıya geçiren sadık dostu ve halifesi kimdir?', 'Hüsâmeddin Çelebi', ['Mevlânâ\'nın düşünce dünyasında fırtınalar estiren Şems-i Tebrîzî', 'Kuyumcu esnafından olup okuma yazması bulunmayan Selahaddin Zerkûb', 'Babasının divanlarını tertip edip tarikatı kuran Sultan Veled'], 'Ahi Türk soyundan gelen Hüsâmeddin Çelebi, Mevlânâ\'dan dervişler için eğitici bir eser istemiş; Mesnevî\'nin 25 bini aşkın beyti Mevlânâ\'nın irticalen söylemesi ve Hüsâmeddin Çelebi\'nin yazmasıyla vücut bulmuştur.'),
  ('Anadolu\'da 13. yüzyıl sonu ve 14. yüzyıl başında kaleme alınan \'Garibnâme\' adlı on iki bin beyitlik dev Türkçe mesnevisinde \'Türk diline kimsene bakmaz idi / Türklere hergiz gönül akmaz idi\' diyerek Türkçeyi bilinçle savunan mutasavvıf şair kimdir?', 'Âşık Paşa', ['Mantıku\'t-Tayr çevirisiyle tanınan Kırşehirli Gülşehrî', 'Yusuf u Züleyha hikâyesini nazmeden Şeyyad Hamza', 'Selçuklu Şehnamesi\'ni Farsça yazan Hoca Dehhânî'], 'Baba İlyas\'ın torunu olup Kırşehir\'de yetişen Âşık Paşa (1272-1332), \'Garibnâme\' adlı dev eseriyle Türkçenin yüksek tasavvuf ve bilim kavramlarını anlatmaya tam yetkin olduğunu ispatlamıştır.'),
  ('Klasik Türk divan şiirinin Anadolu\'daki ilk din dışı (lirik-beşeri) örneklerini 13. yüzyıl sonunda Türkçe gazelleriyle veren ve Sultan III. Alaeddin Keykubad\'ın isteğiyle Farsça bir \'Selçuklu Şehnâmesi\' de yazan şair kimdir?', 'Hoca Dehhânî', ['İlahi aşkı hece ölçüsüyle sade biçimde terennüm eden Yunus Emre', 'Farsça rubaileri ve Divan-ı Kebir\'iyle tanınan Mevlânâ Celâleddin', 'İskendernâme ve Cemşid ü Hurşid mesnevilerini yazan Ahmedî'], 'Horasan\'dan Anadolu\'ya gelen Hoca Dehhânî, tasavvufi-dini çizginin dışında bahar, aşk ve tabiat temalı aruzlu Türkçe gazel ve kasideleriyle Anadolu Divan edebiyatının kurucusu sayılır.'),
  ('Aksaray merkezde Sultan I. Alaeddin Keykubad\'ın babası I. Gıyaseddin Keyhüsrev dönemine veya 1221-1236 arasına tarihlenen ve kırmızı tuğladan örülüp hafif yana yatık gövdesiyle kentin simgesi olan yapı hangisidir?', 'Eğri Minare', ['Sivas Çifte Minareli Medrese\'nin taş kaideli ikiz minareleri', 'Erzurum Ulu Camii\'nin kesme taştan basık gövdeli kulesi', 'Konya İnce Minareli Medrese\'nin çini kuşaklı tuğla minaresi'], 'İtalya\'daki Pisa Kulesi\'ni andıran eğikliği ve kırmızı tuğla işçiliğiyle \'Kızıl Minare\' olarak da anılan Aksaray Eğri Minare, Karahanlı-Büyük Selçuklu tuğla minare üslubunun İç Anadolu\'daki önemli temsilcisidir.'),
  ('Kervansaray, köprü ve darüşşifa gibi kamu yapılarına gelir sağlamak amacıyla şehir merkezlerinde inşa edilen, alt katı dükkân üst katı bekar tüccar odalarından oluşan \'şehir içi hanlar\' kır kervansaraylarından hangi yönüyle ayrılır?', 'Ücretsiz menzil hizmeti yerine kira ve ticaret geliri üreten kentsel iş merkezi olmalarıyla', ['Yalnızca askeri mühimmat ve barut saklamak amacıyla penceresiz yapılmalarıyla', 'Şehir dışındaki dağ geçitlerine kurulup etraflarına derin hendek kazılmasıyla', 'İçlerinde hiçbir alım satım yapılmasına izin verilmeyen ibadethane olmalarıyla'], 'Kır/menzil kervansarayları (Sultan hanları) üç gün ücretsiz konaklama sunan hayır-güvenlik kurumlarıyken; şehir içindeki hanlar (ör. Ziyaeddin, Pamukçular hanları) toptan ticaretin döndüğü ve vakıflara kira geliri getiren ticari yapılardır.'),
  ('Kösedağ Savaşı sonrasındaki siyasi kargaşada başkent Konya\'nın Karamanoğlu-Cimri veya eşkıya kuşatmalarına karşı savunulmasında düzenli ordu yokken surlara çıkıp şehri koruyan sivil milis gücü kimlerden oluşmuştur?', 'Ahi teşkilatına bağlı genç yiğitler ve fütüvvet erbabından', ['Venedik ve Ceneviz ticaret kolonilerinin kiraladığı okçulardan', 'İlhanlı hükümdarının İran\'dan gönderdiği Moğol süvarilerinden', 'Bizans imparatorunun yardıma yolladığı paralı Vareg muhafızlarından'], 'İbn Bîbî ve Aksarayî\'nin kaydettiğine göre merkezi otorite boşluğunda Konya, Kayseri ve daha sonra Ankara\'da \'Ahi ve İğdiş\' birlikleri silahlanarak şehirlerin can, mal ve namus güvenliğini bizzat korumuştur.'),
  ('Afyonkarahisar\'da Sahip Ata\'nın oğlu Nusreddin Hasan döneminde 1272-1277 arasında yaptırılan \'Afyon Ulu Camii\', iç mekânındaki kırk adet ahşap sütunu ve mukarnaslı başlıkları nedeniyle halk arasında hangi isimle tanınmıştır?', 'Kırk Direkli Cami', ['Kubbesi firuze çinilerle örtülü olduğu için Yeşil Cami', 'Çift şerefeli tuğla kulesinden ötürü Çifte Minareli Cami', 'Kayalık tepe eteğine oyulduğu için Mağara Camii'], 'Neccar (marangoz) Emir Hacı Bey\'in eseri olan Afyonkarahisar Ulu Camii, çivisiz ahşap tavanı ve kırk ahşap sütunuyla (\'Kırk Direkli Cami\') Anadolu ahşap direkli cami mimarisinin en seçkin örneklerindendir.'),
  ('1206-1207 Antalya fethinden hemen sonra I. Gıyaseddin Keyhüsrev\'in Venedik ve Kıbrıslı tüccarlara ahidname verirken şehirdeki Hristiyan ve Yahudi mahallelerinin mülkiyet haklarını güvenceye alması ne sağlamıştır?', 'Deniz ticareti deneyimine sahip liman nüfusunun göç etmesini önleyip ekonomiyi derhal canlandırmayı', ['Şehirdeki tüm cami inşaatlarının masrafını Venedik elçiliğine ödetmeyi', 'Antalya limanının yönetimini bağımsız bir İtalyan konsolosluğuna devretmeyi', 'İç Anadolu\'daki çiftçilerin tarımı bırakıp gemiciliğe geçmesini zorunlu kılmayı'], 'Fetih sonrasında yerli tüccar ve zanaatkârlara gösterilen adalet ve mülkiyet güvencesi, Antalya limanının hiçbir kesintiye uğramadan Doğu Akdeniz\'in en işlek antreposuna dönüşmesini sağlamıştır.'),
  ('Kayseri\'nin doğusunda Tuzhisar mevkiinde Sivas kervan yolu üzerinde I. Alaeddin Keykubad tarafından 1232-1236 yıllarında yaptırılan ve Aksaray\'daki eşiyle aynı plan görkemini paylaşan kervansaray hangisidir?', 'Kayseri (Tuzhisar) Sultan Hanı', ['Konya-Aksaray yolunda derin göl kıyısında kurulan Obruk Hanı', 'Antalya-Isparta geçidinde su kaynakları yanındaki Kırkgöz Hanı', 'Tokat-Sivas arasındaki Çamlıbel geçidinde yükselen Yeni Han'], 'Kayseri-Sivas yolunun 47. kilometresindeki Tuzhisar Sultan Hanı, avlu ortasındaki ejder kemerli köşk mescidi ve anıtsal taş işçiliğiyle Aksaray Sultan Hanı\'ndan sonra Anadolu\'nun ikinci büyük Sultan hanıdır.'),
  ('13. yüzyılın son çeyreğinde Anadolu\'ya gelen Venedikli gezgin Marco Polo\'nun seyahatnamesinde \'Turcomania\' (Türkmeneli / Türkiye) halkını anlatırken Türkmenleri ve şehirli unsurları ekonomik iş bölümü açısından nasıl tasvir ettiği görülür?', 'Türkmenlerin yaylalarda seçkin at, katır ve halı ürettiğini; şehirlerde ise zanaat ve ticaretin geliştiğini', ['Anadolu\'da hiçbir yerleşik şehir kalmadığını ve tüm halkın balıkçılıkla geçindiğini', 'Türkmenlerin tarım ve hayvancılığı bırakıp yalnızca gümüş madenlerinde çalıştığını', 'Şehirlerde para kullanılmadığını ve sadece tuz kalıplarıyla alışveriş yapıldığını'], '1271-1272 yıllarında Anadolu\'dan geçen Marco Polo, yaylalarda hayvancılık yapıp nefis halılar dokuyan ve dayanıklı at-katır yetiştiren Türkmenler ile Sivas, Kayseri, Konya\'daki canlı ticaret ve ipekli dokuma üretimini hayranlıkla kaydetmiştir.'),
  ('Türkiye Selçuklularının Kırım\'daki Suğdak limanından başlayıp Sinop-Samsun, Sivas-Kayseri-Konya üzerinden Antalya-Alanya\'ya inen dikey ticaret koridorunu tek devlet çatısı altında birleştirmesi Akdeniz-Karadeniz ticaretinde ne sağlamıştır?', 'Kuzeyin kürk ve köle pazarı ile güneyin baharat ve Akdeniz ticaretini kesintisiz karayoluyla bağlamasını', ['İstanbul Boğazı\'nın tamamen kurutularak gemi geçişinin sona erdirilmesini', 'Mısır\'daki İskenderiye limanının tüm ticari gemilere süresiz kapatılmasını', 'İpek Yolu kervanlarının İran\'a uğramadan doğrudan Afrika çöllerine inmesini'], 'Dördüncü Haçlı Seferi (1204) sonrasında İstanbul ve Boğazlar ticaretinin sarsıldığı dönemde Selçuklular Sinop-Sivas-Konya-Antalya hattını kervansaraylarla donatarak Karadeniz ile Akdeniz arasındaki en güvenli köprüyü kurmuşlardır.'),
  ('1277 yılında Karamanoğlu Mehmed Bey\'in Konya\'da Selçuklu sultanı II. İzzeddin Keykavus\'un oğlu olduğunu iddia ederek tahta çıkardığı \'Alâeddin Siyavuş\' tarihte hangi lakapla anılan olaya ad vermiştir?', 'Cimri Olayı', ['Malya Ovası\'nda güçlükle bastırılan Babailer Ayaklanması', 'Aydın ve Saruhan sahillerinde patlak veren Börklüce İsyanı', 'Amasya ve Tokat çevresinde gelişen Celali Başkaldırısı'], 'İlhanlı ve Selçuklu kuvvetlerine karşı meşruiyet sağlamak isteyen Karamanoğlu Mehmed Bey, Sultan Keykavus\'un oğlu olduğunu öne süren Gıyaseddin/Alaeddin Siyavuş\'u (\'Cimri\') sultan ilan etmiştir.'),
  ('Mevlânâ Celâleddin-i Rûmî\'nin annesi Mümine Hatun\'un türbesini de içinde barındırdığı için \'Mâder-i Mevlânâ Dergâhı\' olarak bilinen Aktekke Camii hangi şehirde yer almaktadır?', 'Karaman', ['Mevlânâ\'nın kırk yılı aşkın yaşayıp vefat ettiği Konya', 'Bahaeddin Veled\'in ilk uğrak noktalarından biri olan Erzincan', 'Selçuklu şehzadelerinin yönetim stajı yaptığı Amasya'], 'Mevlânâ ailesi Konya\'dan önce yedi yıl Larende\'de (Karaman) yaşamış; burada vefat eden annesi Mümine Hatun için Karamanoğlu Alâeddin Bey 1370\'te Aktekke Camii\'ni yaptırmıştır.'),
  ('Erkek evladı bulunmayan Germiyanoğlu II. Yakup Bey\'in 1429 yılında vefat etmeden önce tüm beylik topraklarını Osmanlı Padişahı II. Murad\'a bırakması hangi hukuki yola örnektir?', 'Miras ve vasiyet yoluyla Osmanlı Devleti\'ne katılmaya', ['Haçlı ittifakı karşısında geçici askeri himaye istemeye', 'Ahi loncalarının halk oylamasıyla yönetici seçmesine', 'Deniz aşırı ticaret imtiyazı karşılığında kira devrine'], 'Ankara Savaşı\'ndan sonra yeniden kurulan Germiyanoğulları, II. Yakup Bey\'in vasiyeti üzerine 1429\'da tek damla kan dökülmeden Osmanlı topraklarına katılmıştır.'),
  ('Germiyan sarayında yetişip daha sonra Osmanlı şehzadelerinin de himayesini gören, on bin beyti aşan \'İskendernâme\' mesnevisinin sonuna ilk manzum Osmanlı tarihi bölümünü (\'Dâstân-ı Tevârîh-i Mülûk-i Âl-i Osman\') ekleyen şair kimdir?', 'Ahmedî', ['Garibnâme adlı tasavvufi mesnevisiyle tanınan Âşık Paşa', 'Birgi ve Ayasuluk saraylarında tıp kitapları yazan Hacı Paşa', 'Sivas hükümdarı olup tuyuğlar kaleme alan Kadı Burhaneddin'], '14. yüzyıl Türk edebiyatının en büyük şairlerinden Germiyanlı Taceddin İbrahim Ahmedî, \'İskendernâme\' ve \'Cemşîd ü Hurşîd\' eserleriyle hem bilim hem edebiyat dilini zenginleştirmiştir.'),
  ('Yine Germiyan kültür çevresinde yetişen, göz hekimliği de yapan ve boynuz umarken kulağından olan eşeğin hikâyesiyle toplumsal hiciv şaheseri \'Harnâme\'yi yazan divan şairi kimdir?', 'Şeyhî', ['Düstûrnâme adlı eserinde Umur Bey\'i anlatan Enverî', 'Kenzü\'l-Küberâ adlı siyasetnameyi Türkçeye kazandıran Şeyhoğlu', 'Mantıku\'t-Tayr eserini Anadolu Türkçesine uyarlayan Gülşehrî'], 'Çelebi Mehmed\'i tedavi ettikten sonra kendisine verilen tımar köyüne giderken eski tımar sahiplerince soyulup dövülen Kütahyalı Hekim Sinan (Şeyhî), bu olayı \'Harnâme\' adlı ünlü mesnevisinde hicvetmiştir.'),
  ('İzmir\'in Selçuk (Ayasuluk) ilçesinde Aydınoğlu İsa Bey tarafından 1375 yılında Şamlı Mimar Ali bin Müşaimiş\'e yaptırılan \'İsa Bey Camii\' Türk mimarlık tarihinde hangi geçiş özelliğini temsil eder?', 'Şam Emeviye Camii şemasını Anadolu\'ya uyarlayıp avlulu erken Osmanlı camilerine öncülük etmesini', ['Tamamen tuğladan örülüp hiçbir mermer veya kesme taş malzeme kullanılmamasını', 'Avlusuz ve penceresiz tek kubbeli mescit tipinin en küçük örneği olmasını', 'Kaya kütlesinin içi oyularak yapılan yer altı ibadethanesi niteliği taşımasını'], 'Artemis Tapınağı kalıntılarından devşirme sütunların da kullanıldığı Selçuk İsa Bey Camii, enine gelişen iki kubbeli harimi ve revaklı avlusuyla Selçuklu\'dan Osmanlı klasik cami mimarisine uzanan kilit halkadır.'),
  ('Aydınoğulları sarayında yetişip \'Şifâü\'l-Eskâm\' ve halkın anlayacağı sade Türkçeyle \'Müntehab-ı Şifâ\' adlı eserleri yazdığı için bilim tarihinde \'Anadolu\'nun İbn-i Sînâ\'sı\' unvanıyla anılan büyük hekim kimdir?', 'Celâleddin Hızır', ['Mekanik su otomatları kitabını yazan Cizreli El-Cezerî', 'Gökbilim cetvelleri hazırlayan Kütahyalı Abdülvâcid', 'Cerrahiyetü\'l-Hâniyye adlı resimli eseri yazan Sabuncuoğlu'], 'Kahire\'de eğitim görüp Kalavun Bimaristanı\'nda başhekimlik bile yaptıktan sonra Aydınoğlu İsa Bey\'in davetiyle Ayasuluk/Birgi\'ye dönen Hacı Paşa (ö. 1424?), Anadolu tıbbının en büyük otoritesidir.'),
  ('Milas\'ın hemen güneyindeki sarp tepe üzerinde yer alan ve kazılarda Türkiye\'nin en büyük beylik/Osmanlı sikke definesi ile Ahmet Gazi Medresesi\'nin bulunduğu Menteşeoğulları başkenti hangisidir?', 'Beçin Kalesi ve Kenti', ['Aydınoğullarının kışlık liman merkezi olan Ayasuluk Kalesi', 'Karamanoğullarının Toros geçidindeki kalesi olan Mut Kalesi', 'Hamitoğullarının göl yarımadasındaki merkezi Eğirdir Kalesi'], 'Milas\'a 5 km mesafedeki müstahkem Beçin (Peçin) kenti, Menteşeoğullarının yönetim başkenti olup Orhan Camii, Ahmet Gazi Medresesi ve Kızılhan gibi yapılarıyla tam bir Orta Çağ Türk şehir müzesidir.'),
  ('Kastamonu\'nun Kasaba köyünde Candaroğlu Adil Bey\'in oğlu Mahmut Bey tarafından 1366 yılında yaptırılan \'Mahmut Bey Camii\' dıştan sade moloz taş görünmesine karşın iç mekânında hangi benzersiz hazineyi saklar?', 'Çivisiz ahşap bindirme tavanı ve kökboyası kalemişi nakışlarını', ['Kubbesini tamamen örten saf altın yaldızlı cam mozaiklerini', 'Yirmi adet mermer fil ayağı üzerine oturan çift katlı revaklarını', 'Zeminindeki şifalı sıcak su havuzunu ve mermer sütunlu şadırvanını'], 'UNESCO Dünya Mirası Listesi\'ne de dahil edilen Anadolu ahşap direkli camilerinden Kastamonu Kasaba Köyü Mahmut Bey Camii, 650 yıldır solmayan kökboyalı ahşap nakışları ve Ankaralı Nakkaş Mahmut oğlu Abdullah imzalı kapısıyla ünlüdür.'),
  ('Beyşehir ve çevresinde kurulan \'Eşrefoğulları Beyliği\'nden günümüze ulaşan 1299 tarihli \'Eşrefoğlu Süleyman Bey Camii\', çatısındaki açıklıktan kışın içeri doldurulan karların sedir direkleri nemlendirerek çatlamasını önlediği hangi mimari bölümüyle ünlüdür?', 'Cami ortasındaki karlık havuzuyla', ['Minare tepesindeki rüzgâr gülü saatiyle', 'Mihrap arkasındaki gizli yer altı geçidiyle', 'Avlu duvarındaki döner denge sütunlarıyla'], 'Anadolu\'nun en büyük ahşap direkli camisi olan Beyşehir Eşrefoğlu Camii\'nin tam ortasındaki \'karlık havuzu\', kışın çatıdan atılan karların yavaşça eriyip kırktan fazla sedir sütuna ideal bağıl nem sağlaması için tasarlanmış dahiyane bir mühendislik çözümüdür.'),
  ('İlhanlı Hükümdarı Ebû Said Bahadır Han\'ın ölümünden sonra Sivas ve Kayseri merkezli bağımsız bir devlet kuran, adaletli ve merhametli yönetimi yüzünden Anadolu halkının \'Köse Peygamber\' lakabını taktığı Uygur Türkü hükümdar kimdir?', 'Alâeddin Eretna Bey', ['Sivas tahtını naiplikten devralan Kadı Burhaneddin', 'Tokat ve Sinop\'ta hüküm süren Muineddin Pervane', 'Maraş yaylalarında beylik kuran Zeyneddin Karaca Bey'], 'Timurtaş\'ın Anadolu valiliği sonrasında Orta Anadolu\'da kargaşayı bitirip adil ve düşük vergili bir yönetim kuran Uygur kökenli Sultan Alâeddin Eretna (1335-1352), halk tarafından çok sevilerek \'Köse Peygamber\' diye anılmıştır.'),
  ('Eretna Devleti\'nde kadılık ve vezirlik yaparken 1381\'de Sivas merkezli yönetimi ele geçiren, Akkoyunlu, Memlük, Osmanlı ve Timur tehditlerine karşı on yedi yıl çarpışırken Türk edebiyatında \'tuyuğ\' nazım biçiminin en büyük şairi olan devlet adamı kimdir?', 'Kadı Burhâneddin Ahmed', ['Harnâme ve Hüsrev ü Şirin mesnevilerinin yazarı Şeyhî', 'Garibnâme adlı eseriyle Kırşehir\'de ünlenen Âşık Paşa', 'Osmanlı ilk sadrazamlarından olan Çandarlı Kara Halil'], 'Hem büyük bir İslam hukukçusu, hem gözü pek bir hükümdar hem de Türkçe \'Dîvân\' sahibi lirik-epik bir şair olan Kadı Burhâneddin (1345-1398), dört dizelik milli \'tuyuğ\' nazım şeklinin zirvesidir.'),
  ('Çukurova bölgesinde (Adana, Misis, Tarsus, Sis) Üçoklu Yüreğir Türkmenlerinden Ramazan Bey tarafından kurulan, uzun süre Memlük nüfuzunda kaldıktan sonra 1516-1517\'de Osmanlı\'ya bağlanıp 1608\'e dek iç özerkliğini koruyan en son beylik hangisidir?', 'Ramazanoğulları', ['Muğla ve Milas sahilinde hüküm süren Menteşeoğulları', 'Denizli ve çevresinde dokumacılıkla gelişen İnançoğulları', 'Afyonkarahisar kalesinde varlık gösteren Sahibataoğulları'], 'Çukurova\'daki Ermeni Krallığı kalıntılarını tasfiye ederek bölgeyi Türkleştiren Ramazanoğulları, Yavuz Sultan Selim\'in Mısır seferinde gönüllü itaat etmiş ve 1608\'de Adana vilayeti olana dek babadan oğula sancakbeyliğiyle yönetilmiştir.'),
  ('Adana şehir merkezinde Ramazanoğlu Halil Bey tarafından başlatılıp 1541\'de oğlu Pîrî Mehmed Paşa tarafından tamamlanan, siyah-beyaz taş işçiliği (ablaq) ile Memlük, Selçuklu ve Osmanlı üsluplarını kaynaştıran şaheser hangisidir?', 'Adana Ulu Camii ve Külliyesi', ['Kahramanmaraş\'ta Şems Hatun adına yapılan Hatuniye Camii', 'Karaman merkezde yükselen İbrahim Bey İmaret Külliyesi', 'Manisa\'da Sipil Dağı yamacında kurulan İshak Bey Camii'], 'İznik ve Kütahya çinileriyle süslü iç mekânı, Memlük etkili siyah-beyaz taş kemerleri ve sekizgen minaresiyle Adana Ulu Camii, Ramazanoğulları mimarisinin en görkemli anıtıdır.'),
  ('Batı Anadolu\'da kurulan Karesi, Saruhan, Aydın ve Menteşe beyliklerinin birkaç on yıl içinde güçlü donanmalar kurarak Ege Denizi\'nde söz sahibi olmalarını kolaylaştıran demografik ve coğrafi etken nedir?', 'Bizans\'ın ihmal ettiği yerli kıyı gemicileri ve tersane altyapısını Türkmen savaşçılığıyla birleştirmeleri', ['Orta Asya\'daki Aral Gölü\'nden gemilerini parçalar halinde develerle Ege\'ye taşımaları', 'İspanya ve Portekiz krallıklarından yüzlerce kalyon ve topçu mürettebat satın almaları', 'Ege Denizi\'nde o yüzyılda Venedik ve Ceneviz\'e ait hiçbir savaş gemisinin bulunmaması'], '1261\'de başkenti İstanbul\'a dönen Bizans İmparatoru VIII. Mihail donanmayı dağıtınca işsiz kalan Ege kıyı gemicileri ve kalyon ustaları, adil davranan Türkmen kıyı beylerinin hizmetine girerek gemi inşa bilgisini aktarmıştır.'),
  ('1334 ve 1344 yıllarında Papalık, Venedik, Kıbrıs Krallığı ve Rodos Şövalyelerinin aralarındaki anlaşmazlıkları bırakıp \'Kutsal İttifak\' donanması kurarak doğrudan İzmir limanına saldırmalarının nedeni nedir?', 'Gazi Umur Bey filosunun Ege\'deki Latin ticaret yollarını ve adalarını felç etmesi', ['Aydınoğullarının Cebelitarık Boğazı\'nı kapatarak Atlas Okyanusu\'na açılması', 'İzmir kalesinde Katolik dünyasının kutsal emanetlerinin saklanıyor olması', 'Bizans İmparatoru\'nun İzmir\'i Haçlı şövalyelerine para karşılığı satması'], 'Aydınoğlu Gazi Umur Bey\'in yüzlerce gemilik donanmasıyla Ege\'yi bir Türk denizine çevirmesi Avrupa\'da büyük panik yaratmış; Papa VI. Clemens\'in çağrısıyla kurulan Haçlı donanması 1344\'te İzmir Sahil Kalesi\'ni ele geçirerek Umur Bey\'i denizden kesmiştir.'),
  ('İzmir Sahil (Aşağı) Kalesi 1344\'te Haçlıların eline geçtikten sonra Aydınoğullarının Yukarı Kale\'yi (Kadifekale) tutmayı sürdürürken dış deniz ticaretini hangi alternatif liman kentine kaydırdıkları görülür?', 'Ayasuluk (Selçuk) limanına', ['Karadeniz kıyısındaki Amasra iskelesine', 'Çukurova sahilindeki Yumurtalık koyuna', 'Marmara Denizi\'ndeki Gemlik tersanesine'], 'Haçlıların Liman Kalesi\'ni tutması üzerine Aydınoğlu Hızır ve İsa beyler, Küçük Menderes ağzındaki Ayasuluk\'u (Efes/Selçuk) Venedik ve Ceneviz konsolosluklarının bulunduğu zengin bir uluslararası ticaret merkezine dönüştürmüşlerdir.'),
  ('Eğirdir Gölü\'ne uzanan yarımadanın girişinde Selçuklu kervansarayının hemen karşısına Hamitoğlu Feleküddin Dündar Bey tarafından 1301 yılında eklenip genişletilerek yaptırılan iki katlı yapı hangisidir?', 'Dündar Bey (Taş) Medresesi', ['Beyşehir Gölü kıyısındaki Kubadabad Sarayı', 'Afyonkarahisar merkezdeki Kırk Direkli Cami', 'Kütahya çarşısındaki Germiyan Kurşunlu Camii'], 'Eğirdir\'de II. Gıyaseddin Keyhüsrev döneminden kalma bir hanın taç kapısının da değerlendirildiği iki katlı revaklı Dündar Bey Medresesi, Hamitoğulları mimarisinin simgesidir.'),
  ('İkinci dönem Türk beylikleri mimarisi genel olarak Türkiye Selçuklu klasik mimarisiyle karşılaştırıldığında cami plan gelişiminde gözlenen en belirgin yapısal yenilik nedir?', 'Çok ayaklı loş ulu cami planından aydınlık revaklı avlu ve geniş merkezi kubbe arayışına yönelinmesi', ['Taş ve mermer kullanımının tamamen bırakılarak yalnız kerpiç binalar yapılması', 'Minarelerin cami bitişiğinden kaldırılıp şehir dışındaki tepelere dikilmesi', 'Bütün camilerin alt katlarına at ahırları ve kervansaray depoları eklenmesi'], 'Beylikler dönemi mimarisi (Selçuk İsa Bey, Manisa Ulu, Milas Firuz Bey, Balat İlyas Bey camileri), çok sütunlu Selçuklu ulu cami geleneğinden Osmanlı\'nın tek/merkezi kubbeli ve şadırvan avlulu ferah mekanına geçişi hazırlayan deneysel bir laboratuvardır.'),
  ('14. yüzyılda Kırşehir\'de yaşayan, Ferîdüddin Attâr\'ın ünlü tasavvuf eserini \'Mantıku\'t-Tayr\' (Kuş Dili) adıyla ve Mesnevî\'den hikâyeler katarak zarif bir Anadolu Türkçesiyle nazmeden şair kimdir?', 'Gülşehrî', ['Sivas hükümdarı ve tuyuğ şairi Kadı Burhaneddin', 'Selçuklu sarayının ilk divan şairi Hoca Dehhânî', 'Germiyan sarayının hekim şairi Yusuf Şeyhî'], 'Kırşehir\'de zaviyesi bulunan Ahi-Mevlevî şair Gülşehrî, 1317\'de tamamladığı Türkçe \'Mantıku\'t-Tayr\' ve Farsça \'Feleknâme\' eserleriyle Türkçenin Farsçadan aşağı kalmadığını gururla dile getirmiştir.'),
  ('Osmanlı Devleti\'nin 14. ve 15. yüzyıllarda diğer Anadolu Türk beyliklerini (Karaman, Germiyan, Aydın, Menteşe, Candar) egemenliği altına alma sürecinde Bizans ve Balkan fetihlerinden farklı olarak izlediği ihtiyatlı tutumun nedeni nedir?', 'Müslüman Türk beyliklerine karşı savaşmanın İslam ve gaza kamuoyunda tepki çekmesinden kaçınmak', ['Anadolu topraklarında tarıma elverişli ova ve maden kaynağının hiç bulunmaması', 'Osmanlı ordusunun ateşli silahlar ve süvari sayısı bakımından beyliklerden zayıf olması', 'Avrupa devletlerinin Anadolu beylikleriyle savunma ittifakı kurmuş bulunması'], 'Rumeli\'de gaza ve cihat sancağıyla kolayca meşruiyet bulan Osmanlılar, Müslüman Türk kardeş beylikleri ilhak ederken çeyiz, satın alma, miras, hakemlik veya \'Karamanoğullarının gaza arkadan vurması\' gibi şer\'i fetvalara dayanmaya özen göstermiştir.'),
  ('Fatih Sultan Mehmed döneminde Karaman\'ın (1466-1474) ve Sinop-Kastamonu\'nun (1461) alınmasından sonra bile Güneydoğu sınırındaki Dulkadir ve Ramazan beyliklerine bir süre daha dokunulmamasının dış politika sebebi nedir?', 'Güçlü Memlük Sultanlığı ile erken ve yıpratıcı bir savaşa girmemek için tampon bölgeyi korumak', ['Çukurova ve Maraş dağlarında Osmanlı ordusunun ilerleyebileceği hiçbir geçit bulunmaması', 'Bu iki beyliğin Venedik Cumhuriyeti\'nin resmi deniz koruması altında olması', 'Osmanlı hazinesinin doğu yönlü bir seferi karşılayacak gümüş akçeye sahip olmaması'], 'Dulkadiroğulları ve Ramazanoğulları Mısır-Suriye hâkimi Memlüklerin nüfuz ve tampon kuşağında yer aldığından, kesin ilhakları ancak II. Bayezid sonrasındaki Yavuz Sultan Selim\'in Memlük/Doğu seferleriyle tamamlanmıştır.'),
  ('Afyonkarahisar (Karahisâr-ı Devle) kalesi ve çevresinde ünlü Selçuklu veziri Sahip Ata Fahreddin Ali\'nin oğulları ve torunları tarafından kurularak Germiyanoğullarına dek varlığını sürdüren küçük beylik hangisidir?', 'Sâhibataoğulları', ['Beyşehir Gölü havzasında kurulan Eşrefoğulları', 'Kastamonu yaylasında hüküm süren Çobanoğulları', 'Niksar ve Çarşamba\'da gelişen Tâceddinoğulları'], 'Selçuklu veziri Sahip Ata Fahreddin Ali\'ye ikta/mülk verilen Karahisar\'da oğulları Taceddin Hüseyin ve Nusreddin Hasan ile torunu Şemseddin Ahmed\'in yönettiği beyliğe Sâhibataoğulları (1275-1341) denir.'),
  ('14. yüzyılda Batı Anadolu beyliklerinin Venedik, Ceneviz ve Rodos Şövalyeleriyle imzaladıkları ticaret sözleşmelerinde Avrupalıların Anadolu limanlarından ısrarla satın almak istedikleri başlıca tarım ve hayvancılık ürünleri hangileridir?', 'Buğday, kuru üzüm-incir, balmumu, safran, at ve yünlü dokumalar', ['Kahve çekirdeği, şeker kamışı, patates, kakao ve kauçuk reçinesi', 'Çay yaprağı, karabiber, tarçın, karanfil ve muson kerestesi', 'Balina yağı, fildişi, devekuşu tüyü, kehribar ve porselen'], 'Nüfusu artan İtalyan deniz cumhuriyetleri ve Ege adaları tahıl açığını kapatmak için Menteşe (Balat), Aydın (Ayasuluk) ve Saruhan limanlarından tonlarca buğday, kuru meyve, şap, balmumu, deri ve Türkmen atı ithal etmiştir.'),
  ('Muğla\'nın Yatağan-Milas hattından Kütahya, Birgi, Kastamonu ve Karaman\'a uzanan ikinci dönem beylik başkentlerinin genellikle antik kentlerin tam üstü yerine hemen yakınındaki yamaç veya su başlarında kurulmasının kentsel sonucu ne olmuştur?', 'Yeni ve özgün Türk-İslam şehir merkezlerinin (Birgi, Beçin, Manisa, Balıkesir, Karaman) doğup büyümesi', ['Antik kentlerdeki mermer sütunların denize dökülerek tamamen yok edilmesi', 'Şehirlerin etrafına hendek kazılamadığı için ticaret kervanlarının uğramaması', 'Nüfusun kış aylarında şehirleri boşaltarak mağaralarda yaşamak zorunda kalması'], 'Sıtmalı alüvyal bataklıklara dönüşen eski liman çukurları yerine havadar, tatlı sulu dağ eteklerini (Manisa Sipil eteği, Birgi Bozdağ eteği, Beçin tepesi) seçen Türk beyleri sağlıklı ve bahçeli yeni Türk kentleri kurmuştur.'),
  ('Karamanoğlu II. İbrahim Bey\'in vefatından sonra oğulları Pir Ahmed Bey ile İshak Bey arasında çıkan taht kavgasına hem Akkoyunlu Uzun Hasan\'ın hem de Fatih Sultan Mehmed\'in müdahil olması neyle sonuçlanmıştır?', 'Fatih\'in Konya ve Karaman\'ı zaptedip Otlukbeli Zaferi sonrası Karamanoğlu direncini kesin kırmasıyla', ['Karamanoğulları Beyliği\'nin Venedik donanması yardımıyla Bursa\'yı ele geçirmesiyle', 'İki kardeşin ülkeyi eşit bölüşerek yüz yıl daha bağımsız hüküm sürmesiyle', 'Memlük ordusunun Konya\'ya girerek Orta Anadolu\'yu Kahire\'ye bağlamasıyla'], 'Dış güçlerden yardım arayan Karamanoğlu şehzadelerinin mücadelesi Fatih Sultan Mehmed\'in 1466-1474 seferleriyle Konya ve Larende\'yi Osmanlı\'ya katmasını sağlamış; II. Bayezid devrinde beylik tamamen tarihe karışmıştır.'),
  ('15. yüzyıl ortasında Düstûrnâme adlı manzum tarihini Veziriazam Mahmud Paşa\'ya sunan \'Enverî\'nin bu eseri, Osmanlı tarihinden bile çok hangi Anadolu beyliğinin deniz seferleri için eşsiz bir birincil kaynaktır?', 'Aydınoğulları Beyliği', ['Dulkadiroğulları Beyliği', 'Eşrefoğulları Beyliği', 'Sahibataoğulları Beyliği'], 'Enverî\'nin \'Düstûrnâme\'sinin on sekizinci bölümü bütünüyle Aydınoğlu Mehmed Bey ve özellikle Gazi Umur Bey\'in Ege ve Balkan deniz gazalarını ayrıntılarıyla anlatan tek ve en değerli Türkçe destan-kroniktir.'),
  ('Bursa\'nın fethinden sonra Orhan Gazi devrinde Karesi Beyliği\'nde Dursun Bey ile kardeşi Demirhan Bey arasında başlayan taht mücadelesi Osmanlılara nasıl bir diplomatik fırsat sunmuştur?', 'Dursun Bey\'in yardım isteğiyle iç işlerine karışıp Karesi kalelerini az kayıpla devralma fırsatı', ['Bizans donanmasını kiralayarak Balıkesir ve Bergama\'yı denizden bombalama imkânı', 'Karesi topraklarını Cenevizlilere satarak Bursa camilerinin inşasını finanse etme şansı', 'Her iki şehzadeyi de Rumeli\'ye sürgün edip halkı vergiye bağlama olanağı'], 'Kardeşi Demirhan Bey\'e karşı Orhan Gazi\'den yardım isteyen Dursun Bey\'in Bergama kuşatması sırasında kaleden atılan okla ölmesi ve Karesi ileri gelenlerinin Orhan Gazi\'yi tercih etmesiyle beylik 1345\'te Osmanlı\'ya bağlanmıştır.'),
];
